        <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
            <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>

                <button onClick={onResume} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                    <Play size={18} /> Resume
                </button>

                <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg">
                    <input 
                    type="checkbox" 
                    id="menuSort" 
                    checked={autoSort} 
                    onChange={onToggleSort}
                    className="w-5 h-5 accent-indigo-500"
                    />
                    <label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label>
                </div>

                <button onClick={onResign} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                    <LogOut size={18} /> Resign
                </button>
                <button onClick={onQuit} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2">
                    <ArrowRight size={18} /> Quit to Title
                </button>
            </div>
        </div>
    );
};

import React from 'react';
import { Trash2, X } from 'lucide-react';
import { CardDisplay } from '../CardDisplay';
import { Card, PlayerState } from '../../types';

interface DiscardModalProps {
    viewingDiscard: 'SHARED' | number | null;
    players: PlayerState[];
    onClose: () => void;
    mode: string;
}

export const DiscardModal: React.FC<DiscardModalProps> = ({ viewingDiscard, players, onClose, mode }) => {
    if (viewingDiscard === null) return null;

    const discardCards = viewingDiscard === 'SHARED' 
        ? [...players[0].discard, ...players[1].discard] 
        : (typeof viewingDiscard === 'number' ? players[viewingDiscard].discard : []);

    const title = viewingDiscard === 'SHARED' ? 'Shared Graveyard' : `${players[viewingDiscard].name}'s Graveyard`;

    return (
        <div className="absolute inset-0 z-[110] flex items-center justify-center bg-black/90 backdrop-blur-md" onClick={onClose}>
            <div className="relative w-full max-w-4xl p-8 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-2xl font-bold font-title text-white flex items-center gap-3">
                        <Trash2 className="text-slate-500" />
                        {title}
                    </h2>
                    <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full transition-colors">
                        <X size={24} className="text-slate-400" />
                    </button>
                </div>
                <div className="flex-1 overflow-y-auto p-4 bg-slate-950/50 rounded-lg border border-slate-800">
                    {discardCards.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-48 text-slate-600 italic">
                            No cards in graveyard.
                        </div>
                    ) : (
                        <div className="flex flex-wrap gap-4 justify-center">
                            {discardCards.map((c, i) => (
                                <div key={i} className="hover:scale-110 transition-transform">
                                    <CardDisplay card={c} size="md" />
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <div className="mt-4 text-center text-xs text-slate-500 font-bold uppercase tracking-wider">
                    {discardCards.length} Cards
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard, Rank, LogEntry as LogEntryType } from './types';
import { createDeck, createTutorialDeck, sortHand } from './utils/cards';
import { getEffectiveColor, canBlock, createFieldCard } from './utils/rules';
import { generateId } from './utils/core';
import { getCpuInitSelection, getCpuResourceDecision, getBestMainPhaseAction, getCpuAttackers, getCpuBlocks } from './utils/ai';
import { TUTORIAL_LESSONS } from './data/tutorials';
import { INITIAL_LIFE, MAX_RESOURCES } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, ArrowRight, Trash2, X, Edit3, Cpu, Users, GraduationCap } from 'lucide-react';

// Imported Components
import { LogRenderer } from './components/ui/LogRenderer';
