  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO';

export interface GameState {
  mode: GameMode;
  deck: Card[]; // Shared deck for Street mode
  players: PlayerState[];
  turnPlayer: number; // 0 or 1
  phase: Phase;
  turnCount: number;
  pendingAttackers: string[]; // instanceIds
  pendingBlocks: Record<string, string>; // blockerId -> attackerId
  selectedCardId: string | null; // For hand interaction
  targetMode: 'NONE' | 'QUEEN' | 'KING';
  sourceCardId: string | null; // The card initiating the target mode
  winner: number | null; // 0, 1, or -1 (Draw)
  logs: string[];
}

import { Card, Suit, Rank, Color, FieldCard } from './types';

export const generateId = () => Math.random().toString(36).substr(2, 9);

export const CARD_VALUES: Record<Rank, number> = {
  [Rank.Two]: 2,
  [Rank.Three]: 3,
  [Rank.Four]: 4,
  [Rank.Five]: 5,
  [Rank.Six]: 6,
  [Rank.Seven]: 7,
  [Rank.Eight]: 8,
  [Rank.Nine]: 9,
  [Rank.Ten]: 10,
  [Rank.Jack]: 2, // Cost 2
  [Rank.Queen]: 3, // Cost 3
  [Rank.King]: 4, // Cost 4
  [Rank.Ace]: 1, // Cost 1, Value 1
};

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const shuffle = <T>(array: T[]): T[] => {
  let currentIndex = array.length, randomIndex;
  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }
  return array;
};

// Determine the EFFECTIVE color of a soldier (considering attached Queens)
export const getEffectiveColor = (fieldCard: FieldCard): Color => {
  // If a Queen is attached, the soldier takes the Queen's spectrum
  const attachedQueen = fieldCard.attachedCards.find(c => c.rank === Rank.Queen);
  if (attachedQueen) {
    return attachedQueen.baseColor;
  }
  return fieldCard.card.baseColor;
};

export const canBlock = (attacker: FieldCard, blocker: FieldCard): boolean => {
    // Must be in same lane (Same Effective Color)
    const attackerColor = getEffectiveColor(attacker);
    const blockerColor = getEffectiveColor(blocker);

    // Physical (Black) vs Physical (Black), Magical (Red) vs Magical (Red)
    return attackerColor === blockerColor;
};

export const createFieldCard = (card: Card, ownerId: number): FieldCard => ({
  instanceId: generateId(),
  card,
  ownerId,
  isTapped: false,
  isSummoningSick: true,
  attachedCards: []
});

import React, { useState, useEffect } from 'react';
import { 
  Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, Rank, Suit 
} from './types';
import { createDeck, createFieldCard, getEffectiveColor, canBlock, shuffle } from './utils';
import { 
  ArrowUpCircle, Shield, Sword, RotateCcw, Heart, Layers, AlertCircle, RefreshCw 
} from 'lucide-react';

// --- Constants ---
const INITIAL_LIFE = 20;
const MAX_RESOURCES = 10;
const STARTING_HAND_SIZE = 8; // 8 drawn, then discard 3 for resources = 5 starting hand.

// --- Components ---

const CardDisplay: React.FC<{
  card: Card;
  onClick?: () => void;
  isSelected?: boolean;
  isTapped?: boolean;
  isSummoningSick?: boolean;
  isPlayable?: boolean;
  isTargetable?: boolean;
  isAttacking?: boolean;
  isBlocking?: boolean;
  attachedCards?: Card[];
  size?: 'sm' | 'md' | 'lg';
  showBack?: boolean;
}> = ({ 
  card, onClick, isSelected, isTapped, isSummoningSick, isPlayable, isTargetable, 
  isAttacking, isBlocking, attachedCards, size = 'md', showBack = false 
}) => {
  const attachedQueen = attachedCards?.find(c => c.rank === Rank.Queen);
  const effectiveColor = attachedQueen ? attachedQueen.baseColor : card.baseColor;
  const isRed = effectiveColor === Color.Red;

  const sizeClasses = {
    sm: 'w-12 h-16 text-xs',
    md: 'w-20 h-28 text-sm',
    lg: 'w-32 h-44 text-lg',
  };

  if (showBack) {
    return (
      <div className={`${sizeClasses[size]} bg-indigo-900 border-2 border-slate-700 rounded shadow-md relative overflow-hidden`}>
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-indigo-800 to-indigo-950 opacity-50"></div>
        <div className="w-full h-full flex items-center justify-center text-indigo-400 font-title font-bold opacity-20">BATTLE</div>
      </div>
    );
  }

  return (
    <div 
      onClick={onClick}
      className={`
        ${sizeClasses[size]} 
        relative bg-slate-200 rounded shadow-md select-none transition-all duration-200 cursor-pointer
        flex flex-col justify-between p-1
        ${isRed ? 'text-red-900' : 'text-slate-900'}
        ${isSelected ? 'ring-4 ring-yellow-400 -translate-y-2' : 'border border-slate-400'}
        ${isPlayable ? 'ring-2 ring-green-400 hover:-translate-y-1' : ''}
        ${isTargetable ? 'ring-4 ring-red-500 animate-pulse' : ''}
        ${isTapped ? 'rotate-90 grayscale-[0.5]' : ''}
        ${isAttacking ? 'ring-4 ring-red-600 -translate-y-4 shadow-xl z-20' : ''}
        ${isBlocking ? 'ring-4 ring-blue-500 -translate-y-4 shadow-lg' : ''}
      `}
    >
      {/* Attached Queen Indicator */}
      {attachedQueen && (
        <div className={`absolute -top-2 -right-2 w-6 h-6 rounded-full flex items-center justify-center border-2 border-white shadow-sm z-30 ${attachedQueen.baseColor === Color.Red ? 'bg-red-600' : 'bg-slate-900'}`}>
          <span className="text-[10px] text-white font-bold">Q</span>
        </div>
      )}

      {isSummoningSick && !isTapped && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40">
           <span className="text-2xl font-bold text-slate-500">zZ</span>
        </div>
      )}

      <div className="flex justify-between leading-none">
        <span className="font-bold font-title">{card.rank}</span>
        <span>{card.suit}</span>
      </div>

      <div className="self-center text-2xl opacity-20">{card.suit}</div>

      <div className="flex justify-between leading-none rotate-180">
        <span className="font-bold font-title">{card.rank}</span>
        <span>{card.suit}</span>
      </div>

      {/* Badges for Ace/Face Cards */}
      {card.rank === Rank.Ace && <div className="absolute bottom-1 right-1 text-[10px] font-bold bg-black text-white px-1 rounded">DEATH</div>}
    </div>
  );
};

// --- Main App Component ---

export const App = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [initSelectedIds, setInitSelectedIds] = useState<string[]>([]);

  // Initialize Game
  const startGame = (mode: GameMode) => {
    let sharedDeck: Card[] = [];
    if (mode === 'STREET') {
      sharedDeck = createDeck();
    }

    const createPlayer = (id: number, name: string): PlayerState => ({
      id,
      name,
      life: INITIAL_LIFE,
      hand: [],
      library: mode === 'PRO' ? createDeck() : [],
      resources: [],
      field: [],
      discard: [],
      hasAttackedThisTurn: false,
    });

    const newState: GameState = {
      mode,
      deck: sharedDeck,
      players: [createPlayer(0, 'Player 1'), createPlayer(1, 'Player 2')],
      turnPlayer: 0,
      phase: Phase.INIT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      logs: ['Game Started. Deployment Phase.'],
    };

    // Draw initial hands
    const drawCount = STARTING_HAND_SIZE; // 8 cards
    newState.players.forEach(player => {
      const sourceDeck = mode === 'STREET' ? newState.deck : player.library;
      const drawn = sourceDeck.splice(0, drawCount);
      player.hand = drawn;
    });

    setGameState(newState);
    setInitSelectedIds([]);
  };

  // Helper to add log
  const addLog = (msg: string) => {
    setGameState(prev => {
      if (!prev) return null;
      return { ...prev, logs: [msg, ...prev.logs].slice(0, 50) };
    });
  };

  // --- Actions ---

  const handleInitSelection = (cardId: string) => {
    if (initSelectedIds.includes(cardId)) {
      setInitSelectedIds(prev => prev.filter(id => id !== cardId));
    } else if (initSelectedIds.length < 3) {
      setInitSelectedIds(prev => [...prev, cardId]);
    }
  };

  const confirmInitSelection = () => {
    if (!gameState) return;
    const player = gameState.players[gameState.turnPlayer];

    // Move selected to resources
    const selectedCards = player.hand.filter(c => initSelectedIds.includes(c.id));
    const newHand = player.hand.filter(c => !initSelectedIds.includes(c.id));

    // Create FieldCards for resources (enter tapped/untapped? Tapped usually to prevent immediate use if not turn 1, but rule says face down. We treat as generic resources.)
    // Logic: Resources are tapped to pay costs.
    const newResources = selectedCards.map(c => createFieldCard(c, player.id));

    // Update state
    const newPlayers = [...gameState.players];
    newPlayers[gameState.turnPlayer] = {
      ...player,
      hand: newHand,
      resources: newResources
    };

    const nextPlayer = gameState.turnPlayer === 0 ? 1 : 0;
    const isRoundOver = nextPlayer === 0; // Back to P1

    let nextPhase = gameState.phase;
    let nextTurnPlayer = nextPlayer;

    if (isRoundOver) {
      nextPhase = Phase.UPKEEP; // Start game loop
      nextTurnPlayer = 0; // Player 1 starts
      addLog("Deployment complete. Player 1 begins.");
    } else {
      setInitSelectedIds([]); // Reset for P2
    }

    setGameState({
      ...gameState,
      players: newPlayers,
      turnPlayer: nextTurnPlayer,
      phase: nextPhase
    });
  };

  const drawCard = (playerId: number) => {
    if (!gameState) return;
    const playerIndex = gameState.players.findIndex(p => p.id === playerId);
    const player = gameState.players[playerIndex];
    const sourceDeck = gameState.mode === 'STREET' ? gameState.deck : player.library;

    if (sourceDeck.length === 0) {
      addLog(`Deck empty! ${player.name} cannot draw.`);
      return;
    }

    const card = sourceDeck.shift();
    if (card) {
      player.hand.push(card);
      addLog(`${player.name} draws a card.`);
    }
  };

  const nextPhase = () => {
    if (!gameState) return;

    const currentPhase = gameState.phase;
    let next = currentPhase;
    let nextTurnPlayer = gameState.turnPlayer;
    let nextTurnCount = gameState.turnCount;

    // Phase State Machine
    switch (currentPhase) {
      case Phase.UPKEEP:
        // Untap logic
        const p = gameState.players[gameState.turnPlayer];
        p.resources.forEach(r => r.isTapped = false);
        p.field.forEach(f => {
          f.isTapped = false;
          f.isSummoningSick = false;
        });

        // Skip draw on Turn 1 for Player 1
        if (gameState.turnCount === 1 && gameState.turnPlayer === 0) {
          next = Phase.RESOURCE_START;
          addLog("Turn 1: Draw step skipped.");
        } else {
          next = Phase.DRAW;
        }
        break;
      case Phase.DRAW:
        drawCard(gameState.turnPlayer);
        next = Phase.RESOURCE_START;
        break;
      case Phase.RESOURCE_START:
        // If player skipped resource action, go to MAIN
        next = Phase.MAIN;
        break;
      case Phase.RESOURCE_ADD_SELECT:
      case Phase.RESOURCE_SWAP_SELECT_HAND:
      case Phase.RESOURCE_SWAP_SELECT_PILE:
         // If canceling out of resource mode
         next = Phase.MAIN;
         break;
      case Phase.MAIN:
         next = Phase.END; 
         break;
      case Phase.ATTACK_DECLARE:
         if (gameState.pendingAttackers.length === 0) {
           next = Phase.MAIN; // Cancel attack
         } else {
           // Commit attacks
           const attacker = gameState.players[gameState.turnPlayer];
           attacker.field.forEach(f => {
             if (gameState.pendingAttackers.includes(f.instanceId)) {
               f.isTapped = true;
             }
           });
           attacker.hasAttackedThisTurn = true;
           next = Phase.BLOCK_DECLARE;
           // Switch active control conceptually to defender for blocking
         }
         break;
      case Phase.BLOCK_DECLARE:
         next = Phase.DAMAGE;
         break;
      case Phase.DAMAGE:
         resolveCombat();
         return; // Resolve function handles state update
      case Phase.END:
         nextTurnPlayer = gameState.turnPlayer === 0 ? 1 : 0;
         if (nextTurnPlayer === 0) nextTurnCount++;
         next = Phase.UPKEEP;
         addLog(`--- Turn ${nextTurnCount} ---`);
         break;
    }

    setGameState({
      ...gameState,
      phase: next,
      turnPlayer: nextTurnPlayer,
      turnCount: nextTurnCount,
      selectedCardId: null, // Clear selections
      targetMode: 'NONE'
    });
  };

  // --- Resource Logic ---
  const handleResourceClick = (option: 'ADD' | 'SWAP') => {
    if (!gameState) return;
    if (option === 'ADD') {
      setGameState({ ...gameState, phase: Phase.RESOURCE_ADD_SELECT });
      addLog("Select a card from hand to add as resource.");
    } else {
      setGameState({ ...gameState, phase: Phase.RESOURCE_SWAP_SELECT_HAND });
      addLog("Select a card from hand to swap in.");
    }
  };

  const executeResourceAction = (cardId: string, swapTargetInstanceId?: string) => {
    if (!gameState) return;
    const player = gameState.players[gameState.turnPlayer];
    const cardIdx = player.hand.findIndex(c => c.id === cardId);
    if (cardIdx === -1) return;

    const [card] = player.hand.splice(cardIdx, 1);
    const newRes = createFieldCard(card, player.id);
    newRes.isTapped = true; // Enters tapped

    if (gameState.phase === Phase.RESOURCE_ADD_SELECT) {
      player.resources.push(newRes);
      addLog("Resource added.");
    } else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && swapTargetInstanceId) {
      const resIdx = player.resources.findIndex(r => r.instanceId === swapTargetInstanceId);
      if (resIdx === -1) return;
      const oldRes = player.resources[resIdx];
      // Return old resource to hand
      player.hand.push(oldRes.card);
      // Replace with new
      player.resources[resIdx] = newRes;
      addLog("Resource swapped.");
    }

    setGameState({
      ...gameState,
      phase: Phase.MAIN,
      selectedCardId: null
    });
  };

  // --- Main Phase Logic ---
  const handleHandCardClick = (card: Card) => {
    if (!gameState) return;
    const player = gameState.players[gameState.turnPlayer];

    // Phase: Init
    if (gameState.phase === Phase.INIT) {
      handleInitSelection(card.id);
      return;
    }

    // Phase: Resource Add
    if (gameState.phase === Phase.RESOURCE_ADD_SELECT) {
      executeResourceAction(card.id);
      return;
    }

    // Phase: Resource Swap (Step 1)
    if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND) {
      setGameState({ ...gameState, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE });
      addLog("Select a resource pile to swap with.");
      return;
    }

    // Phase: Main (Playing Cards)
    if (gameState.phase === Phase.MAIN) {
      // Check resource cost
      const availableResources = player.resources.filter(r => !r.isTapped).length;
      if (availableResources < card.cost) {
        addLog(`Not enough resources! Need ${card.cost}.`);
        return;
      }

      // Handle Tactics Targets
      if (card.rank === Rank.King) {
        setGameState({ ...gameState, selectedCardId: card.id, targetMode: 'KING' });
        addLog("Select a target unit of the SAME color to execute.");
        return;
      }
      if (card.rank === Rank.Queen) {
        setGameState({ ...gameState, selectedCardId: card.id, targetMode: 'QUEEN' });
        addLog("Select a target unit to shift color.");
        return;
      }
      if (card.rank === Rank.Jack) {
        // Jack Effect: Draw 2
        playCard(card);
        drawCard(player.id);
        drawCard(player.id);
        addLog("Jack played: Reinforcements (Draw 2).");
        return;
      }

      // Play Unit
      playCard(card);
    }
  };

  const playCard = (card: Card) => {
    if (!gameState) return;
    const player = gameState.players[gameState.turnPlayer];
    const cardIdx = player.hand.findIndex(c => c.id === card.id);
    if (cardIdx === -1) return;

    // Pay Cost
    let cost = card.cost;
    for (const res of player.resources) {
      if (cost > 0 && !res.isTapped) {
        res.isTapped = true;
        cost--;
      }
    }

    // Remove from hand
    player.hand.splice(cardIdx, 1);

    // Effect or Field
    if ([Rank.King, Rank.Queen, Rank.Jack].includes(card.rank)) {
       player.discard.push(card);
    } else {
       // Conscript Soldier
       const newUnit = createFieldCard(card, player.id);
       player.field.push(newUnit);
       addLog(`Conscripted ${card.rank} of ${card.suit}.`);
    }

    setGameState({ ...gameState, selectedCardId: null, targetMode: 'NONE' });
  };

  const handleFieldCardClick = (fieldCard: FieldCard) => {
    if (!gameState) return;
    const currentPlayer = gameState.players[gameState.turnPlayer];
    const opponent = gameState.players[gameState.turnPlayer === 0 ? 1 : 0];

    // Resource Swap Target
    if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && fieldCard.ownerId === currentPlayer.id) {
       // Check if clicked card is actually a resource? 
       // NOTE: We need a separate handler for Resource Click vs Field Click ideally.
       // Reusing this for simplicity if passed properly.
       return; 
    }

    // Targeting (King/Queen)
    if (gameState.targetMode !== 'NONE' && gameState.selectedCardId) {
      const sourceCard = currentPlayer.hand.find(c => c.id === gameState.selectedCardId);
      if (!sourceCard) return;

      if (gameState.targetMode === 'KING') {
        const targetColor = getEffectiveColor(fieldCard);
        if (targetColor === sourceCard.baseColor) {
           // Valid Kill
           const targetOwner = gameState.players.find(p => p.id === fieldCard.ownerId);
           if (targetOwner) {
             targetOwner.field = targetOwner.field.filter(f => f.instanceId !== fieldCard.instanceId);
             targetOwner.discard.push(fieldCard.card);
             playCard(sourceCard);
             addLog(`King Executed ${fieldCard.card.rank} of ${fieldCard.card.suit}.`);
           }
        } else {
           addLog("Invalid Target: Colors must match.");
        }
      }

      if (gameState.targetMode === 'QUEEN') {
         fieldCard.attachedCards.push(sourceCard);
         playCard(sourceCard); // Logic handles discard, but here we attach instead. 
         // Fix: playCard puts it in discard. We need to prevent that or pull it back.
         // Let's manually handle Queen payment to avoid complexity.
         const p = gameState.players[gameState.turnPlayer];
         const cIdx = p.discard.findIndex(c => c.id === sourceCard.id);
         if (cIdx > -1) p.discard.splice(cIdx, 1); // Remove from discard if playCard put it there
         addLog(`Queen Shifted ${fieldCard.card.rank} of ${fieldCard.card.suit}.`);
      }
      return;
    }

    // Attack Declaration
    if (gameState.phase === Phase.ATTACK_DECLARE && fieldCard.ownerId === currentPlayer.id) {
       if (fieldCard.isTapped || fieldCard.isSummoningSick) return;

       if (gameState.pendingAttackers.includes(fieldCard.instanceId)) {
         setGameState({
           ...gameState,
           pendingAttackers: gameState.pendingAttackers.filter(id => id !== fieldCard.instanceId)
         });
       } else {
         setGameState({
           ...gameState,
           pendingAttackers: [...gameState.pendingAttackers, fieldCard.instanceId]
         });
       }
    }

    // Block Declaration
    if (gameState.phase === Phase.BLOCK_DECLARE && fieldCard.ownerId !== currentPlayer.id) {
       // Current player is attacker during block phase (waiting), Defender (opponent) is acting.
       // We need to invert perspective or allow opponent to click.
       // For Hotseat: "TurnPlayer" is Attacker. 
       const defenderId = gameState.turnPlayer === 0 ? 1 : 0;

       if (fieldCard.ownerId === defenderId) {
           // Selecting a blocker
           if (fieldCard.isTapped) return;
           setGameState({ ...gameState, selectedCardId: fieldCard.instanceId }); // Select blocker
       } else if (fieldCard.ownerId === gameState.turnPlayer) {
           // Selecting an attacker to block
           if (gameState.selectedCardId && gameState.pendingAttackers.includes(fieldCard.instanceId)) {
               // Validate Spectrum
               const blocker = opponent.field.find(f => f.instanceId === gameState.selectedCardId);
               if (blocker && canBlock(fieldCard, blocker)) {
                   const newBlocks = { ...gameState.pendingBlocks, [gameState.selectedCardId]: fieldCard.instanceId };
                   setGameState({ ...gameState, pendingBlocks: newBlocks, selectedCardId: null });
               } else {
                   addLog("Invalid Block! Wrong Spectrum.");
               }
           }
       }
    }
  };

  const handleResourcePileClick = (res: FieldCard) => {
     if (gameState?.phase === Phase.RESOURCE_SWAP_SELECT_PILE && gameState.selectedCardId) {
        executeResourceAction(gameState.selectedCardId, res.instanceId);
     }
  };

  const resolveCombat = () => {
     if (!gameState) return;
     const attacker = gameState.players[gameState.turnPlayer];
     const defender = gameState.players[gameState.turnPlayer === 0 ? 1 : 0];

     const attackers = attacker.field.filter(f => gameState.pendingAttackers.includes(f.instanceId));

     attackers.forEach(atk => {
        // Find blockers for this attacker
        const blockerIds = Object.keys(gameState.pendingBlocks).filter(bid => gameState.pendingBlocks[bid] === atk.instanceId);

        if (blockerIds.length === 0) {
           // Unblocked
           const damage = atk.card.rank === Rank.Ace ? 1 : atk.card.numericValue;
           defender.life -= damage;
           addLog(`${atk.card.rank}${atk.card.suit} deals ${damage} damage to Life.`);
        } else {
           // Blocked
           blockerIds.forEach(bid => {
              const blk = defender.field.find(f => f.instanceId === bid);
              if (!blk) return;

              const atkVal = atk.card.numericValue;
              const blkVal = blk.card.numericValue;
              const atkIsAce = atk.card.rank === Rank.Ace;
              const blkIsAce = blk.card.rank === Rank.Ace;

              let atkDies = false;
              let blkDies = false;

              if (atkIsAce) {
                 atkDies = true; 
                 blkDies = true; // Ace deathtouch
              } else if (blkIsAce) {
                 blkDies = true;
                 atkDies = true;
              } else {
                 if (atkVal > blkVal) blkDies = true;
                 else if (blkVal > atkVal) atkDies = true;
                 else { atkDies = true; blkDies = true; }
              }

              if (atkDies) {
                 attacker.field = attacker.field.filter(f => f.instanceId !== atk.instanceId);
                 attacker.discard.push(atk.card);
              }
              if (blkDies) {
                 defender.field = defender.field.filter(f => f.instanceId !== blk.instanceId);
                 defender.discard.push(blk.card);
              }
           });
        }
     });

     // Check Win
     if (defender.life <= 0) {
        setGameState({ ...gameState, winner: attacker.id, phase: Phase.GAME_OVER });
     } else {
        // Cleanup
        setGameState({ 
           ...gameState, 
           phase: Phase.MAIN, 
           pendingAttackers: [], 
           pendingBlocks: {} 
        });
     }
  };


  if (!gameState) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-slate-900 text-white">
         <div className="text-center space-y-8">
            <h1 className="text-6xl font-black font-title tracking-widest text-indigo-500">BATTLE</h1>
            <div className="flex gap-4 justify-center">
               <button onClick={() => startGame('STREET')} className="px-6 py-3 bg-slate-800 border border-slate-600 rounded hover:bg-slate-700 transition">Street Mode (Shared Deck)</button>
               <button onClick={() => startGame('PRO')} className="px-6 py-3 bg-indigo-900 border border-indigo-600 rounded hover:bg-indigo-800 transition">Pro Mode (Separate Decks)</button>
            </div>
         </div>
      </div>
    );
  }

  const activePlayer = gameState.players[gameState.turnPlayer];
  const opponent = gameState.players[gameState.turnPlayer === 0 ? 1 : 0];

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans">
       {/* Top Bar (Opponent Info) */}
       <div className="flex justify-between items-center p-4 bg-slate-900 border-b border-slate-800">
           <div className="flex items-center gap-4">
              <div className="text-xl font-bold font-title text-indigo-400">{opponent.name}</div>
              <div className="flex items-center gap-1 text-red-500 font-bold"><Heart size={16} fill="currentColor"/> {opponent.life}</div>
              <div className="text-xs text-slate-500">Hand: {opponent.hand.length} | Deck: {gameState.mode === 'STREET' ? gameState.deck.length : opponent.library.length}</div>
           </div>
           <div>
              <div className="text-xs text-slate-500 font-bold tracking-widest">{gameState.mode} MODE</div>
           </div>
       </div>

       {/* Battle Area */}
       <div className="flex-1 flex flex-col relative overflow-hidden">

           {/* Opponent Field (Top) */}
           <div className="flex-1 flex flex-col justify-start p-4 bg-slate-900/50">
               {/* Opponent Resources */}
               <div className="flex gap-2 justify-center mb-2 opacity-80">
                   {opponent.resources.map(res => (
                       <div key={res.instanceId} className="transition-transform duration-300">
                          <CardDisplay card={res.card} showBack size="sm" isTapped={res.isTapped} />
                       </div>
                   ))}
               </div>

               {/* Opponent Units */}
               <div className="flex gap-2 justify-center flex-wrap">
                   {opponent.field.map(fc => (
                       <CardDisplay 
                          key={fc.instanceId} 
                          card={fc.card} 
                          isTapped={fc.isTapped}
                          attachedCards={fc.attachedCards}
                          onClick={() => handleFieldCardClick(fc)}
                          isTargetable={gameState.targetMode !== 'NONE'}
                          isBlocking={!!Object.keys(gameState.pendingBlocks).find(b => b === fc.instanceId)}
                       />
                   ))}
               </div>
           </div>

           {/* Center Phase Indicator */}
           <div className="h-12 bg-slate-800 flex items-center justify-between px-8 border-y border-slate-700 shadow-lg z-10">
               <div className="font-title font-bold text-amber-500 tracking-widest">
                  {gameState.phase.replace('_', ' ')}
               </div>

               <div className="flex gap-2">
                 {gameState.phase === Phase.INIT && (
                   <button 
                     disabled={initSelectedIds.length !== 3}
                     onClick={confirmInitSelection}
                     className="px-4 py-1 bg-indigo-600 rounded text-sm font-bold disabled:opacity-50"
                   >
                     Confirm Resources ({initSelectedIds.length}/3)
                   </button>
                 )}

                 {gameState.phase === Phase.RESOURCE_START && (
                   <>
                      <button onClick={() => handleResourceClick('ADD')} className="flex items-center gap-1 px-3 py-1 bg-emerald-700 rounded text-xs hover:bg-emerald-600"><ArrowUpCircle size={14}/> Add Resource</button>
                      <button onClick={() => handleResourceClick('SWAP')} className="flex items-center gap-1 px-3 py-1 bg-amber-700 rounded text-xs hover:bg-amber-600"><RotateCcw size={14}/> Swap Resource</button>
                      <button onClick={nextPhase} className="px-3 py-1 bg-slate-700 rounded text-xs hover:bg-slate-600">Skip</button>
                   </>
                 )}

                 {gameState.phase === Phase.MAIN && (
                   <>
                     {!activePlayer.hasAttackedThisTurn && <button onClick={() => setGameState({...gameState, phase: Phase.ATTACK_DECLARE})} className="flex items-center gap-1 px-4 py-1 bg-red-700 rounded text-sm font-bold hover:bg-red-600"><Sword size={14}/> Attack</button>}
                     <button onClick={nextPhase} className="px-4 py-1 bg-slate-700 rounded text-sm font-bold hover:bg-slate-600">End Turn</button>
                   </>
                 )}

                 {gameState.phase === Phase.ATTACK_DECLARE && (
                    <button onClick={nextPhase} className="px-4 py-1 bg-red-600 rounded text-sm font-bold animate-pulse">Confirm Attackers</button>
                 )}

                 {gameState.phase === Phase.BLOCK_DECLARE && (
                    <div className="text-sm text-blue-300 animate-pulse">Opponent Declaring Blocks... (Hotseat: Click Defender then Attacker) <button onClick={nextPhase} className="ml-2 px-2 py-0.5 bg-blue-700 rounded text-xs">Confirm Blocks</button></div>
                 )}
               </div>
           </div>

           {/* Player Field (Bottom) */}
           <div className="flex-1 flex flex-col justify-end p-4 bg-slate-900/50">
               {/* Player Units */}
               <div className="flex gap-2 justify-center flex-wrap mb-4">
                   {activePlayer.field.map(fc => (
                       <CardDisplay 
                          key={fc.instanceId} 
                          card={fc.card} 
                          isTapped={fc.isTapped}
                          isSummoningSick={fc.isSummoningSick}
                          attachedCards={fc.attachedCards}
                          onClick={() => handleFieldCardClick(fc)}
                          isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                          isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                          isTargetable={gameState.targetMode !== 'NONE'}
                       />
                   ))}
               </div>

               {/* Player Resources */}
               <div className="flex gap-2 justify-center">
                   {activePlayer.resources.map(res => (
                       <div 
                         key={res.instanceId} 
                         className="transition-transform duration-300 hover:-translate-y-2 cursor-pointer"
                         onClick={() => handleResourcePileClick(res)}
                       >
                          <CardDisplay card={res.card} size="sm" isTapped={res.isTapped} />
                       </div>
                   ))}
               </div>
           </div>
       </div>

       {/* Player Hand & Info */}
       <div className="h-48 bg-slate-900 border-t border-slate-800 flex">
            {/* Info Panel */}
            <div className="w-48 p-4 border-r border-slate-800 flex flex-col justify-between">
                <div>
                   <div className="text-2xl font-bold font-title text-indigo-400">{activePlayer.name}</div>
                   <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2"><Heart size={32} fill="currentColor"/> {activePlayer.life}</div>
                </div>
                <div className="text-xs text-slate-500">
                    <div>Resources: {activePlayer.resources.filter(r => !r.isTapped).length}/{activePlayer.resources.length}</div>
                </div>
            </div>

            {/* Hand */}
            <div className="flex-1 p-4 flex items-center justify-center gap-[-4rem]">
                <div className="flex -space-x-4">
                    {activePlayer.hand.map(card => (
                        <div key={card.id} className="transition-transform hover:-translate-y-4 hover:z-10">
                             <CardDisplay 
                                card={card} 
                                onClick={() => handleHandCardClick(card)}
                                isSelected={initSelectedIds.includes(card.id) || gameState.selectedCardId === card.id}
                                isPlayable={gameState.phase === Phase.MAIN && activePlayer.resources.filter(r => !r.isTapped).length >= card.cost}
                             />
                        </div>
                    ))}
                </div>
            </div>

            {/* Log Panel */}
            <div className="w-64 bg-slate-950 p-2 overflow-y-auto font-mono text-xs text-slate-400 border-l border-slate-800">
                {gameState.logs.map((log, i) => (
                    <div key={i} className="mb-1 border-b border-slate-800 pb-1">{log}</div>
                ))}
            </div>
       </div>

       {/* Game Over Overlay */}
       {gameState.phase === Phase.GAME_OVER && (
           <div className="absolute inset-0 bg-black/90 flex items-center justify-center z-50">
               <div className="text-center">
                   <h2 className="text-6xl font-black text-white mb-4">GAME OVER</h2>
                   <p className="text-2xl text-indigo-400 mb-8">
                       {gameState.players[gameState.winner!].name} Wins!
                   </p>
                   <button onClick={() => setGameState(null)} className="px-8 py-3 bg-white text-black font-bold rounded hover:bg-slate-200">Main Menu</button>
               </div>
           </div>
       )}
    </div>
  );
};

