                   {(gameState.phase === Phase.RESOURCE_ADD_SELECT || gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND || gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE) && isInteractive && (
                       <button onClick={cancelResourceAction} className="bg-slate-700 p-3 rounded-full text-white shadow-lg">
                           <X size={24} />
                       </button>
                   )}
                   {gameState.phase === Phase.MAIN && isInteractive && (
                       <>
                           {!bottomPlayer.hasAttackedThisTurn && (
                               <button id="btn-attack-phase" onClick={handleAttackPhaseClick} className="bg-rose-600 p-3 rounded-full text-white shadow-lg">
                                   <Sword size={24} />
                               </button>
