export const App: React.FC = () => {
  // --- State ---
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [menuStep, setMenuStep] = useState<'MODE' | 'PLAYERS' | 'TUTORIAL_MENU'>('MODE');

  // UI State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showResignModal, setShowResignModal] = useState(false);
  const [showQuitModal, setShowQuitModal] = useState(false);
  const [showPauseMenu, setShowPauseMenu] = useState(false);
  const [viewingDiscard, setViewingDiscard] = useState<'SHARED' | number | null>(null);
  const [sandboxToolsOpen, setSandboxToolsOpen] = useState(false);
  const [autoSortHand, setAutoSortHand] = useState(true);

  // Sandbox State
  const [sandboxSearchTerm, setSandboxSearchTerm] = useState('');
  const [sandboxTargetPlayer, setSandboxTargetPlayer] = useState<0 | 1>(0);
  const [selectedSandboxCard, setSelectedSandboxCard] = useState<Card | null>(null);

  // Refs for animations
  const p1Ref = useRef<HTMLDivElement>(null);
  const p2Ref = useRef<HTMLDivElement>(null);

  // --- Derived State Helpers ---
  const turnPlayer = gameState ? gameState.players[gameState.turnPlayer] : null;
  const bottomPlayerId = 0; // Assume human/local player is 0 for perspective
  const bottomPlayer = gameState ? gameState.players[bottomPlayerId] : null;
  const topPlayer = gameState ? gameState.players[bottomPlayerId === 0 ? 1 : 0] : null;

  // Who is making decisions right now?
  // Usually the turn player, EXCEPT during BLOCK_DECLARE (defender decides)
  const activeDecisionPlayerId = gameState 
      ? (gameState.phase === Phase.BLOCK_DECLARE ? (gameState.turnPlayer === 0 ? 1 : 0) : gameState.turnPlayer)
      : 0;

  // --- Game Initialization ---

  const initGame = (mode: GameMode, isCpu: boolean, deck: Card[]) => {
    const p1: PlayerState = {
        id: 0, name: 'Player 1', isCpu: false, life: INITIAL_LIFE,
        hand: [], library: [], resources: [], field: [], discard: [],
        consecutiveDrawFailures: 0, hasAttackedThisTurn: false
    };

    const p2: PlayerState = {
        id: 1, name: isCpu ? 'CPU' : 'Player 2', isCpu: isCpu, life: INITIAL_LIFE,
        hand: [], library: [], resources: [], field: [], discard: [],
        consecutiveDrawFailures: 0, hasAttackedThisTurn: false
    };

    if (mode === 'STREET' || mode === 'SANDBOX') {
        const d = [...deck];
        // Draw initial 8
        for(let i=0; i<8; i++) {
            if (d.length > 0) p1.hand.push(d.pop()!);
            if (d.length > 0) p2.hand.push(d.pop()!);
        }
        setGameState({
            mode, deck: d, players: [p1, p2], turnPlayer: 0, startingPlayerId: 0,
            phase: Phase.INIT_SELECT, turnCount: 1, pendingAttackers: [], pendingBlocks: {},
            selectedCardId: null, targetMode: 'NONE', sourceCardId: null, winner: null,
            logs: [{ id: generateId(), text: 'Welcome to Battle!' }],
            initSelectedIds: [], recentDamage: {}, activeCombatCardId: null
        });
    } else if (mode === 'PRO') {
        // Pro logic: separate decks
        p1.library = createDeck();
        p2.library = createDeck();
        for(let i=0; i<8; i++) {
             if (p1.library.length > 0) p1.hand.push(p1.library.pop()!);
             if (p2.library.length > 0) p2.hand.push(p2.library.pop()!);
        }
        setGameState({
            mode, deck: [], players: [p1, p2], turnPlayer: 0, startingPlayerId: 0,
            phase: Phase.INIT_SELECT, turnCount: 1, pendingAttackers: [], pendingBlocks: {},
            selectedCardId: null, targetMode: 'NONE', sourceCardId: null, winner: null,
            logs: [{ id: generateId(), text: 'Pro Mode Started.' }],
            initSelectedIds: [], recentDamage: {}, activeCombatCardId: null
        });
    }
  };

  const handleStartGame = (isCpu: boolean) => {
      initGame('STREET', isCpu, createDeck());
  };

  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'STREET' || mode === 'PRO') {
          setMenuStep('PLAYERS');
      } else if (mode === 'TUTORIAL') {
          setMenuStep('TUTORIAL_MENU');
      } else if (mode === 'SANDBOX') {
          initGame('SANDBOX', false, createDeck());
      }
  };

  // --- Core Game Actions ---

  const addLog = (text: string) => {
      setGameState(prev => {
          if (!prev) return null;
          return {
              ...prev,
              logs: [...prev.logs, { id: generateId(), text }].slice(-50)
          };
      });
  };

  const confirmAttack = () => {
      if (!gameState) return;
      if (gameState.pendingAttackers.length === 0) {
          // No attackers, skip to post-combat
          setGameState(prev => prev ? ({...prev, phase: Phase.MAIN, hasAttackedThisTurn: true}) : null);
          addLog("No attacks declared.");
      } else {
          setGameState(prev => prev ? ({...prev, phase: Phase.BLOCK_DECLARE}) : null);
          addLog(`${gameState.players[gameState.turnPlayer].name} declares attacks!`);
      }
  };

  const confirmBlocks = () => {
      if (!gameState) return;
      setGameState(prev => prev ? ({...prev, phase: Phase.DAMAGE}) : null);
      addLog("Blocks confirmed. Resolving combat...");
      resolveCombat();
  };

  const resolveCombat = () => {
      // In a real implementation this would be complex with animations.
      // For this fix, we will just apply damage logic immediately or via a timeout simulation.
      // Logic placeholder:
      setTimeout(() => {
          if (!gameState) return;
          // Apply damage logic here (simplified for this fix)
          // Then move to MAIN phase
           setGameState(prev => {
               if (!prev) return null;
               // ... calculations ...
               return {...prev, phase: Phase.MAIN, pendingAttackers: [], pendingBlocks: {}};
           });
      }, 1000);
  };

  const confirmInitSelection = () => {
    if (!gameState) return;
    const pid = activeDecisionPlayerId;
    const player = gameState.players[pid];

    // Must select exactly 3
    if (gameState.initSelectedIds.length !== 3) return;

    setGameState(prev => {
        if (!prev) return null;
        const next = { ...prev };
        const p = next.players[pid];

        // Move selected to resources
        const selectedCards = p.hand.filter(c => next.initSelectedIds.includes(c.id));
        const remainingHand = p.hand.filter(c => !next.initSelectedIds.includes(c.id));

        p.hand = remainingHand;
        selectedCards.forEach(c => {
            p.resources.push(createFieldCard(c, pid));
        });

        // If P1 done, P2 turn? Or game start?
        // Basic logic: if P1 just went and P2 needs to go, switch active.
        // If both done, determine start player and go to UPKEEP.

        // Assuming simultaneous select for simplicity in this mockup, or sequential.
        if (pid === 0) {
             // P1 done, active becomes P2
             // In a real app we might handle CPU auto selection here
             next.turnPlayer = 1; // Temporarily use turnPlayer to track init turn
             next.initSelectedIds = [];
        } else {
            // Both done
            next.phase = Phase.UPKEEP;
            next.turnPlayer = next.startingPlayerId; // Reset to start player
            next.initSelectedIds = [];
            next.logs.push({id: generateId(), text: "Game Start!"});
        }
        return next;
    });
  };

  const toggleCardSelection = (cardId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          const current = prev.initSelectedIds;
          if (current.includes(cardId)) {
              return { ...prev, initSelectedIds: current.filter(id => id !== cardId) };
          } else {
              if (current.length < 3) {
                  return { ...prev, initSelectedIds: [...current, cardId] };
              }
              return prev;
          }
      });
  };

  // --- Rendering ---

  if (!gameState) {
      return (
          <div className="min-h-screen bg-slate-950 flex items-center justify-center text-slate-100 font-sans overflow-hidden">
             <MainMenu 
                menuStep={menuStep}
                setMenuStep={setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGame}
                handleSpectateClick={() => initGame('STREET', true, createDeck())}
                startLesson={(id) => console.log('Start lesson', id)}
             />
          </div>
      );
  }

  // Determine active view
  const isInitPhase = gameState.phase === Phase.INIT_SELECT;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans overflow-hidden relative selection:bg-indigo-500/30">

        {/* Modals */}
        <EndTurnModal show={showEndTurnModal} onCancel={() => setShowEndTurnModal(false)} onConfirm={() => {/* End turn logic */ setShowEndTurnModal(false); }} />
        <ResignModal show={showResignModal} onCancel={() => setShowResignModal(false)} onConfirm={() => { setGameState(prev => prev ? {...prev, winner: prev.players.find(p => p.id !== bottomPlayerId)?.id ?? 1, phase: Phase.GAME_OVER} : null); setShowResignModal(false); }} />
        <QuitModal show={showQuitModal} onCancel={() => setShowQuitModal(false)} onConfirm={() => { setGameState(null); setShowQuitModal(false); }} />
        <PauseMenu show={showPauseMenu} onResume={() => setShowPauseMenu(false)} onResign={() => setShowResignModal(true)} onQuit={() => setShowQuitModal(true)} autoSort={autoSortHand} onToggleSort={() => setAutoSortHand(!autoSortHand)} />
        <DiscardModal viewingDiscard={viewingDiscard} players={gameState.players} onClose={() => setViewingDiscard(null)} mode={gameState.mode} />

        {/* Sandbox Tools */}
        {sandboxToolsOpen && (
            <SandboxTools 
                gameState={gameState} 
                setGameState={setGameState}
                sandboxSearchTerm={sandboxSearchTerm}
                setSandboxSearchTerm={setSandboxSearchTerm}
                sandboxTargetPlayer={sandboxTargetPlayer}
                setSandboxTargetPlayer={setSandboxTargetPlayer}
                selectedSandboxCard={selectedSandboxCard}
                setSelectedSandboxCard={setSelectedSandboxCard}
                setSandboxToolsOpen={setSandboxToolsOpen}
                setShowPlaySetup={() => {}} 
            />
        )}

        {/* Top Bar */}
        <div className="absolute top-0 left-0 w-full h-12 bg-slate-900 border-b border-slate-800 flex justify-between items-center px-4 z-50">
            <div className="flex items-center gap-4">
                <button onClick={() => setShowPauseMenu(true)} className="p-2 hover:bg-slate-800 rounded text-slate-400 hover:text-white transition-colors">
                    <Menu size={20} />
                </button>
                <div className="font-title font-bold text-slate-300 tracking-wider">
                    BATTLE <span className="text-xs text-slate-600 ml-2">{gameState.mode}</span>
                </div>
            </div>

            <div className="flex items-center gap-2">
                 <button onClick={() => setSandboxToolsOpen(!sandboxToolsOpen)} className={`p-1.5 rounded ${sandboxToolsOpen ? 'bg-amber-500 text-slate-900' : 'text-slate-500 hover:text-white'}`}>
                     <RotateCcw size={16} /> {/* Using Icon as placeholder for sandbox toggle if desired */}
                 </button>
            </div>
        </div>

        {/* Game Area */}
        <div className="pt-14 pb-4 px-4 h-screen flex flex-col gap-2">

            {/* Top Player Area */}
            <div className={`flex-1 relative transition-opacity duration-500 ${activeDecisionPlayerId === topPlayer?.id ? 'opacity-100' : 'opacity-80'}`}>
                {/* Top Hand (Hidden/Backs) */}
                <div className="absolute -top-10 left-1/2 -translate-x-1/2 flex gap-1 transform rotate-180 scale-75">
                    {topPlayer?.hand.map((c, i) => (
                        <CardDisplay key={c.id} card={c} showBack={true} size="sm" />
                    ))}
                </div>

                {/* Top Resources */}
                <div className="absolute top-4 right-8 flex gap-1 flex-wrap w-48 justify-end">
                    {topPlayer?.resources.map(r => (
                        <div key={r.instanceId} className="transform rotate-180 scale-75">
                             <CardDisplay card={r.card} size="sm" isTapped={r.isTapped} />
                        </div>
                    ))}
                </div>

                {/* Top Field */}
                 <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-4">
                     {topPlayer?.field.map(f => (
                         <div key={f.instanceId} className="transform rotate-180">
                             <CardDisplay card={f.card} size="md" isTapped={f.isTapped} isSummoningSick={f.isSummoningSick} />
                         </div>
                     ))}
                 </div>
            </div>

            {/* Mid Area (Combat/Phase Info) */}
            <div className="h-24 flex items-center justify-center relative pointer-events-none">
                 <div className="text-4xl font-black text-slate-800 uppercase tracking-[1em] select-none opacity-50">
                     {gameState.phase.replace('_', ' ')}
                 </div>

                 {/* Logs */}
                 <div className="absolute right-4 bottom-0 w-64 flex flex-col items-end pointer-events-none">
                     {gameState.logs.slice(-3).map(log => (
                         <LogEntry key={log.id} text={log.text} />
                     ))}
                 </div>
            </div>

            {/* Bottom Player Area */}
            <div className={`flex-1 relative transition-opacity duration-500 ${activeDecisionPlayerId === bottomPlayer?.id ? 'opacity-100' : 'opacity-90'}`}>
                 {/* Bottom Field */}
                 <div className="absolute top-4 left-1/2 -translate-x-1/2 flex gap-4">
                     {bottomPlayer?.field.map(f => (
                         <CardDisplay 
                            key={f.instanceId} 
                            card={f.card} 
                            size="md" 
                            isTapped={f.isTapped} 
                            isSummoningSick={f.isSummoningSick}
                            isSelected={gameState.pendingAttackers.includes(f.instanceId)}
                            onClick={() => {
                                if (gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === bottomPlayerId) {
                                    // Toggle attacker
                                    setGameState(prev => {
                                        if(!prev) return null;
                                        const current = prev.pendingAttackers;
                                        if (current.includes(f.instanceId)) return {...prev, pendingAttackers: current.filter(id => id !== f.instanceId)};
                                        return {...prev, pendingAttackers: [...current, f.instanceId]};
                                    })
                                }
                            }}
                         />
                     ))}
                 </div>

                 {/* Bottom Resources */}
                 <div className="absolute bottom-32 left-8 flex gap-1 flex-wrap w-48">
                    {bottomPlayer?.resources.map(r => (
                        <div key={r.instanceId} className="transform scale-75 origin-bottom-left">
                             <CardDisplay card={r.card} size="sm" isTapped={r.isTapped} />
                        </div>
                    ))}
                 </div>

                 {/* Bottom Hand */}
                 <div className="absolute bottom-[-60px] left-1/2 -translate-x-1/2 flex gap-[-20px] hover:bottom-0 transition-all duration-300 px-4 pb-4">
                     {bottomPlayer?.hand.map((c, i) => (
                         <div 
                            key={c.id} 
                            className={`transform transition-all duration-300 hover:-translate-y-12 hover:scale-110 cursor-pointer ${gameState.initSelectedIds.includes(c.id) ? '-translate-y-10 ring-2 ring-amber-400 rounded' : ''}`}
                            style={{ marginLeft: i === 0 ? 0 : '-30px' }}
                            onClick={() => isInitPhase ? toggleCardSelection(c.id) : null}
                         >
                            <CardDisplay card={c} size="md" />
                         </div>
                     ))}
                 </div>

                 {/* Action Bar */}
                 <div className="absolute bottom-4 right-4 flex flex-col gap-2 pointer-events-auto">
                      {isInitPhase && activeDecisionPlayerId === bottomPlayerId && (
                          <button 
                            disabled={gameState.initSelectedIds.length !== 3}
                            onClick={confirmInitSelection}
                            className="bg-amber-500 hover:bg-amber-400 text-slate-900 font-bold px-6 py-3 rounded shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                              Confirm Resources ({gameState.initSelectedIds.length}/3)
                          </button>
                      )}

                      {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === bottomPlayerId && (
                          <button id="btn-confirm-attackers" onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12 px-6">
                              Confirm Attackers
                          </button>
                      )}

                      {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayerId && (
                          <button id="btn-confirm-blocks" onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12 px-6">
                              Confirm Blocks
                          </button>
                      )}

                      {gameState.phase === Phase.MAIN && activeDecisionPlayerId === bottomPlayerId && (
                          <>
                             <button onClick={() => setGameState(prev => prev ? ({...prev, phase: Phase.ATTACK_DECLARE}) : null)} className="bg-rose-700 hover:bg-rose-600 text-white font-bold px-4 py-2 rounded">
                                 Attack Phase
                             </button>
                             <button onClick={() => setShowEndTurnModal(true)} className="bg-slate-700 hover:bg-slate-600 text-white font-bold px-4 py-2 rounded">
                                 End Turn
                             </button>
                          </>
                      )}
                 </div>
            </div>

        </div>

        {/* Phase Overlays */}
        {gameState.phase === Phase.GAME_OVER && (
            <div className="absolute inset-0 bg-black/80 flex items-center justify-center z-50">
                <div className="text-center">
                    <h1 className="text-6xl font-black text-amber-500 mb-4">{gameState.winner === bottomPlayerId ? 'VICTORY' : 'DEFEAT'}</h1>
                    <button onClick={() => setGameState(null)} className="bg-white text-slate-900 px-8 py-3 rounded font-bold hover:scale-105 transition-transform">
                        Return to Menu
                    </button>
                </div>
            </div>
        )}
    </div>
  );
};

