                       <button id="btn-confirm-blocks" onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg h-12 flex items-center justify-center gap-2">
                           CONFIRM BLOCKS
                       </button>
                   )}
