import { LogEntry } from './components/ui/LogEntry';
import { MainMenu } from './components/screens/MainMenu';
import { SandboxTools } from './components/tools/SandboxTools';
import { Trash2, Menu, Play, X, RotateCcw, Swords, Shield } from 'lucide-react';
import { EndTurnModal, ResignModal, QuitModal, PauseMenu } from './components/modals/GameModals';
import { DiscardModal } from './components/modals/DiscardModal';
import { LogRenderer } from './components/ui/LogRenderer';

export const App: React.FC = () => {
    // --- UI State ---
    const [menuStep, setMenuStep] = useState<'MODE' | 'PLAYERS' | 'TUTORIAL_MENU'>('MODE');
    const [showPauseMenu, setShowPauseMenu] = useState(false);
    const [viewingDiscard, setViewingDiscard] = useState<'SHARED' | number | null>(null);
    const [autoSort, setAutoSort] = useState(true);

    // --- Sandbox State ---
    const [sandboxSearchTerm, setSandboxSearchTerm] = useState("");
    const [sandboxTargetPlayer, setSandboxTargetPlayer] = useState<0 | 1>(0);
    const [selectedSandboxCard, setSelectedSandboxCard] = useState<Card | null>(null);
    const [sandboxToolsOpen, setSandboxToolsOpen] = useState(false);
    const [showPlaySetup, setShowPlaySetup] = useState(false);

    // --- Game State ---
    const [gameState, setGameState] = useState<GameState | null>(null);

    // --- Derived State ---
    const activeDecisionPlayerId = gameState?.phase === Phase.BLOCK_DECLARE 
        ? (gameState.turnPlayer === 0 ? 1 : 0)
        : gameState?.turnPlayer ?? 0;

    // Assuming Player 0 is "Bottom" (Human/Local) and Player 1 is "Top" (Opponent/CPU)
    const bottomPlayer = gameState?.players[0];
    const topPlayer = gameState?.players[1];

    const isInteractive = gameState ? (
        !gameState.players[activeDecisionPlayerId].isCpu
    ) : false;

    // --- Handlers ---

    const handleStartGame = (isCpu: boolean) => {
        const deck = createDeck();
        const p1Hand = deck.splice(0, STARTING_HAND_SIZE + 3); // 8 cards total (5 hand + 3 resources)
        const p2Hand = deck.splice(0, STARTING_HAND_SIZE + 3);

        const newState: GameState = {
            mode: 'STREET',
            deck,
            players: [
                { id: 0, name: 'Player 1', isCpu: false, life: INITIAL_LIFE, hand: p1Hand, library: [], resources: [], field: [], discard: [], consecutiveDrawFailures: 0, hasAttackedThisTurn: false },
                { id: 1, name: 'Player 2', isCpu: isCpu, life: INITIAL_LIFE, hand: p2Hand, library: [], resources: [], field: [], discard: [], consecutiveDrawFailures: 0, hasAttackedThisTurn: false }
            ],
            turnPlayer: 0,
            startingPlayerId: 0,
            phase: Phase.INIT_SELECT,
            turnCount: 1,
            pendingAttackers: [],
            pendingBlocks: {},
            selectedCardId: null,
            targetMode: 'NONE',
            sourceCardId: null,
            winner: null,
            logs: [{ id: generateId(), text: 'Game Started. Choose 3 cards to be your initial resources.' }],
            initSelectedIds: [],
            recentDamage: {},
            activeCombatCardId: null
        };
        setGameState(newState);
    };

    const confirmBlocks = () => {
        if (!gameState) return;
        setGameState(prev => {
            if (!prev) return null;
            return {
                ...prev,
                phase: Phase.DAMAGE,
                logs: [...prev.logs, { id: generateId(), text: 'Blocks confirmed. Resolving damage...' }]
            };
        });

        // Simulate damage resolution delay
        setTimeout(() => {
            setGameState(prev => {
                if(!prev) return null;
                // Simple turn change logic for prototype
                const nextTurnPlayer = prev.turnPlayer === 0 ? 1 : 0;
                return {
                    ...prev,
                    phase: Phase.UPKEEP,
                    turnPlayer: nextTurnPlayer,
                    turnCount: prev.turnPlayer === 1 ? prev.turnCount + 1 : prev.turnCount,
                    pendingAttackers: [],
                    pendingBlocks: {},
                    logs: [...prev.logs, { id: generateId(), text: `Turn ${prev.turnPlayer === 1 ? prev.turnCount + 1 : prev.turnCount}: ${prev.players[nextTurnPlayer].name}'s Turn` }]
                };
            });
        }, 1000);
    };

    const handleModeSelect = (mode: GameMode) => {
        if (mode === 'TUTORIAL') {
             setMenuStep('TUTORIAL_MENU');
        } else if (mode === 'SANDBOX') {
             handleStartGame(true); // Sandbox starts with CPU but enables tools
             setGameState(prev => prev ? { ...prev, mode: 'SANDBOX' } : null);
             setSandboxToolsOpen(true);
        } else {
             setMenuStep('PLAYERS');
        }
    };

    const startLesson = (lessonId: string) => {
        // Placeholder for tutorial start
        handleStartGame(true);
    };

    // --- Render ---

    if (!gameState) {
        return (
            <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
                <MainMenu 
                    menuStep={menuStep}
                    setMenuStep={setMenuStep}
                    handleModeSelect={handleModeSelect}
                    handleStartGameClick={(isCpu) => handleStartGame(isCpu)}
                    handleSpectateClick={() => handleStartGame(true)} // Spectate: CPU vs CPU? Logic not fully implemented
                    startLesson={startLesson}
                />
            </div>
        );
    }

    if (!bottomPlayer || !topPlayer) return null;

    return (
        <div className="relative w-full h-screen bg-slate-950 overflow-hidden select-none font-sans text-slate-200">
            {/* Background Texture */}
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-5 pointer-events-none"></div>

            {/* Top Bar */}
            <div className="absolute top-0 left-0 right-0 h-14 bg-slate-900/80 backdrop-blur border-b border-slate-700 flex items-center justify-between px-4 z-50">
                <div className="flex items-center gap-4">
                    <button onClick={() => setShowPauseMenu(true)} className="p-2 hover:bg-slate-800 rounded text-slate-400 hover:text-white transition-colors">
                        <Menu size={20} />
                    </button>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-500 tracking-wider">TURN {gameState.turnCount}</span>
                        <span className="text-sm font-bold text-indigo-400">{gameState.phase.replace(/_/g, ' ')}</span>
                    </div>
                </div>

                {/* Sandbox Toggle */}
                {gameState.mode === 'SANDBOX' && (
                    <button onClick={() => setSandboxToolsOpen(!sandboxToolsOpen)} className={`p-2 rounded font-bold text-xs flex items-center gap-2 ${sandboxToolsOpen ? 'bg-amber-500 text-slate-900' : 'bg-slate-800 text-amber-500'}`}>
                        <Swords size={16} /> SANDBOX TOOLS
                    </button>
                )}
            </div>

            {/* Sandbox Tools Panel */}
            {sandboxToolsOpen && (
                <SandboxTools 
                    gameState={gameState}
                    setGameState={setGameState}
                    sandboxSearchTerm={sandboxSearchTerm}
                    setSandboxSearchTerm={setSandboxSearchTerm}
                    sandboxTargetPlayer={sandboxTargetPlayer}
                    setSandboxTargetPlayer={setSandboxTargetPlayer}
                    selectedSandboxCard={selectedSandboxCard}
                    setSelectedSandboxCard={setSelectedSandboxCard}
                    setSandboxToolsOpen={setSandboxToolsOpen}
                    setShowPlaySetup={setShowPlaySetup}
                />
            )}

            {/* Game Board Area */}
            <div className="absolute inset-0 pt-14 pb-20 flex flex-col">
                {/* Top Player (Opponent) Area */}
                <div className="flex-1 relative border-b border-slate-800/50 bg-slate-900/20">
                     <div className="absolute top-4 left-1/2 -translate-x-1/2 flex gap-1">
                        {/* Opponent Hand (Backs) */}
                        {topPlayer.hand.map((c, i) => (
                             <div key={c.id} style={{ marginLeft: i > 0 ? '-20px' : 0 }} className="relative">
                                 <CardDisplay card={c} showBack={!gameState.isSandboxRun} size="sm" />
                             </div>
                        ))}
                     </div>
                     <div className="absolute top-4 right-4 text-center">
                         <div className="text-2xl font-black text-red-500">{topPlayer.life}</div>
                         <div className="text-[10px] text-slate-500 uppercase font-bold">Life</div>
                     </div>
                </div>

                {/* Battlefield */}
                <div className="flex-[2] flex relative">
                    {/* Left Lane (Physical/Black) */}
                    <div className="flex-1 border-r border-slate-800/50 relative bg-slate-900/30 flex flex-col justify-center items-center gap-8">
                         <div className="opacity-10 absolute inset-0 flex items-center justify-center pointer-events-none">
                             <Swords size={120} />
                         </div>
                         {/* Top Units */}
                         <div className="flex gap-2">
                             {topPlayer.field.filter(f => f.card.baseColor === Color.Black).map(f => (
                                 <CardDisplay key={f.instanceId} card={f.card} size="md" orientation="top" />
                             ))}
                         </div>
                         {/* Bottom Units */}
                         <div className="flex gap-2">
                             {bottomPlayer.field.filter(f => f.card.baseColor === Color.Black).map(f => (
                                 <CardDisplay key={f.instanceId} card={f.card} size="md" orientation="bottom" />
                             ))}
                         </div>
                    </div>

                    {/* Right Lane (Magical/Red) */}
                    <div className="flex-1 relative bg-red-900/5 flex flex-col justify-center items-center gap-8">
                         <div className="opacity-10 absolute inset-0 flex items-center justify-center pointer-events-none text-red-500">
                             <Shield size={120} />
                         </div>
                         {/* Top Units */}
                         <div className="flex gap-2">
                             {topPlayer.field.filter(f => f.card.baseColor === Color.Red).map(f => (
                                 <CardDisplay key={f.instanceId} card={f.card} size="md" orientation="top" />
                             ))}
                         </div>
                         {/* Bottom Units */}
                         <div className="flex gap-2">
                             {bottomPlayer.field.filter(f => f.card.baseColor === Color.Red).map(f => (
                                 <CardDisplay key={f.instanceId} card={f.card} size="md" orientation="bottom" />
                             ))}
                         </div>
                    </div>
                </div>

                {/* Bottom Player (User) Area */}
                <div className="flex-1 relative border-t border-slate-800/50 bg-slate-900/20">
                     <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-[-1rem]">
                        {/* Player Hand */}
                        {bottomPlayer.hand.map((c, i) => (
                             <div key={c.id} 
                                  className="relative transition-transform hover:-translate-y-4 hover:z-10" 
                                  style={{ marginLeft: i > 0 ? '-30px' : 0 }}
                             >
                                 <CardDisplay 
                                    card={c} 
                                    size="md" 
                                    isPlayable={gameState.phase === Phase.MAIN && isInteractive}
                                 />
                             </div>
                        ))}
                     </div>
                     <div className="absolute bottom-4 right-4 text-center">
                         <div className="text-2xl font-black text-emerald-500">{bottomPlayer.life}</div>
                         <div className="text-[10px] text-slate-500 uppercase font-bold">Life</div>
                     </div>
                     <div className="absolute bottom-4 left-4 flex gap-1 flex-wrap w-40">
                         {bottomPlayer.resources.map((f, i) => (
                             <div key={f.instanceId} className={`${f.isTapped ? 'opacity-50 grayscale' : ''}`}>
                                 <CardDisplay card={f.card} size="sm" />
                             </div>
                         ))}
                     </div>
                </div>
            </div>

            {/* UI Overlay Controls */}
            <div className="absolute bottom-0 w-full p-4 pointer-events-none z-30">
                <div className="max-w-6xl mx-auto grid grid-cols-12 gap-4 items-end">
                    <div className="col-span-12 md:col-span-4 lg:col-span-3 pointer-events-auto flex gap-2">
                        {/* Action Buttons based on Phase */}
                        {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id && isInteractive && (
                            <button id="btn-confirm-blocks" onClick={confirmBlocks} className="flex-1 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg h-12 flex items-center justify-center gap-2">
                                CONFIRM BLOCKS
                            </button>
                        )}
                        {/* Add Phase.INIT_SELECT logic button just in case */}
                        {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === bottomPlayer.id && isInteractive && (
                             <button onClick={() => {
                                 setGameState(prev => prev ? { ...prev, phase: Phase.MAIN } : null)
                             }} className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded shadow-lg h-12 flex items-center justify-center gap-2">
                                 CONFIRM RESOURCES
                             </button>
                        )}
                    </div>
                </div>
            </div>

            {/* Logs Sidebar */}
            <div className="absolute top-20 left-4 w-72 z-40 bottom-60 overflow-y-auto space-y-1 pointer-events-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent flex flex-col-reverse">
                {gameState.logs.map((log) => (
                    <LogEntry key={log.id} text={`${log.text}`} />
                ))}
            </div>

            {/* Modals */}
            <PauseMenu 
                show={showPauseMenu} 
                onResume={() => setShowPauseMenu(false)} 
                onResign={() => { setShowPauseMenu(false); setGameState(null); }} 
                onQuit={() => { setShowPauseMenu(false); setGameState(null); }}
                autoSort={autoSort}
                onToggleSort={() => setAutoSort(!autoSort)}
            />

            <DiscardModal 
                viewingDiscard={viewingDiscard} 
                players={gameState.players} 
                onClose={() => setViewingDiscard(null)} 
                mode={gameState.mode} 
            />

        </div>
    );
};

