  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Changed to array to allow overlapping animations
  const [damageAnims, setDamageAnims] = useState<DamageAnimInstance[]>([]);

  const [explosions, setExplosions] = useState<{ id: string, x: number, y: number }[]>([]);

  const gameStateRef = useRef<GameState | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null); // Top Player (or generic P2 on mobile)
  const bottomLifeRef = useRef<HTMLDivElement>(null); // Bottom Player (or generic P1 on mobile)

  // Refs for deck locations (named generically top/bottom)
  const bottomDeckRef = useRef<HTMLDivElement>(null);
  const topDeckRef = useRef<HTMLDivElement>(null);

  const handRef = useRef<HTMLDivElement>(null);
  const cpuHandRef = useRef<HTMLDivElement>(null);
  const isDrawingInitialRef = useRef(false);

  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const addLog = (prev: GameState, message: string): LogEntryType[] => {
    return [{ id: generateId(), text: message }, ...prev.logs];
  };

  const startGame = useCallback((mode: GameMode, cpuConfig: { p1: boolean, p2: boolean }, lessonId?: string) => {
    // Reset Modal States
    setShowQuitModal(false);
    setShowResignModal(false);
    setShowMenu(false);
    setShowEndTurnModal(false);

    let tutorialConfig = null;
    let initialPhase = mode === 'SANDBOX' ? Phase.MAIN : Phase.INIT_SELECT;

    if (mode === 'TUTORIAL' && lessonId) {
        tutorialConfig = TUTORIAL_LESSONS.find(l => l.id === lessonId);
        if (tutorialConfig && tutorialConfig.setup) {
            initialPhase = tutorialConfig.setup.phase!;
        }
    }

    // 1. Setup Data
    let sharedDeck: Card[] = [];
    if (mode === 'STREET') sharedDeck = createDeck();
    else if (mode === 'TUTORIAL' && !tutorialConfig?.setup) sharedDeck = createTutorialDeck();

    const createPlayer = (id: number, name: string, isCpu: boolean): PlayerState => {
      let hand: Card[] = [];
      let resources: FieldCard[] = [];
      let field: FieldCard[] = [];
      let life = INITIAL_LIFE;

      // Handle Tutorial Lesson Setup
      if (mode === 'TUTORIAL' && tutorialConfig?.setup) {
          if (id === 0) {
              hand = tutorialConfig.setup.p1Hand || [];
              resources = (tutorialConfig.setup.p1Resources || []).map(c => createFieldCard(c, 0));
              if (tutorialConfig.setup.p1Field) {
                  field = tutorialConfig.setup.p1Field.map(c => {
                      const fc = createFieldCard(c, 0);
                      fc.instanceId = c.id; // Force ID to match card ID for tutorial logic
                      fc.isSummoningSick = false;
                      return fc;
                  });
              }
              if (tutorialConfig.setup.p1Life) life = tutorialConfig.setup.p1Life;
          } else {
              hand = tutorialConfig.setup.p2Hand || [];
              if (tutorialConfig.setup.p2Field) {
                  field = tutorialConfig.setup.p2Field.map(c => {
                      const fc = createFieldCard(c, 1);
                      fc.instanceId = c.id; // Force ID to match card ID for tutorial logic
                      fc.isSummoningSick = false;
                      return fc;
                  });
              }
              if (tutorialConfig.setup.p2Life) life = tutorialConfig.setup.p2Life;
          }
      }

      return {
        id,
        name,
        isCpu,
        life,
        hand, 
        library: mode === 'PRO' ? createDeck() : [],
        resources,
        field,
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, cpuConfig.p1 ? "CPU 1" : "Player 1", cpuConfig.p1);
    const p2 = createPlayer(1, cpuConfig.p2 ? "CPU 2" : "Player 2", cpuConfig.p2);

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0, 
      startingPlayerId: 0, // Placeholder, set by coin flip
      phase: initialPhase,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [{ id: generateId(), text: `Game Started. Mode: ${mode}.` }],
      tutorialState: mode === 'TUTORIAL' && tutorialConfig ? {
          active: true,
          lessonId, // Store lesson ID for persistence
          currentStepIndex: 0,
          steps: tutorialConfig.steps
      } : undefined
    };

    if (mode === 'SANDBOX' || mode === 'TUTORIAL') {
        setGameState(initialState);
        setMenuStep('MODE');
        setIsCoinFlipping(false); // No coin flip in tutorial
        setShowMenu(false);
        if (mode === 'SANDBOX') setSandboxToolsOpen(true);
        else setSandboxToolsOpen(false);
    } else {
        setGameState(initialState);
        setMenuStep('MODE'); 
        setIsCoinFlipping(true);
        setShowMenu(false); 
        setSandboxToolsOpen(false);
    }

  }, [autoSort]);

  // Initial Draw Effect
  useEffect(() => {
    if (gameState && gameState.mode !== 'SANDBOX' && gameState.mode !== 'TUTORIAL' && gameState.phase === Phase.INIT_SELECT && !isCoinFlipping) {
      if (!isDrawingInitialRef.current) {
        const p1 = gameState.players[0];
        const p2 = gameState.players[1];

        if (p1.hand.length === 0 || p2.hand.length === 0) {
             isDrawingInitialRef.current = true;
             (async () => {
                 await drawCards(0, 8);
                 await drawCards(1, 8);
                 setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Deployment Phase: Select 3 resources.") } : null);
                 isDrawingInitialRef.current = false;
             })();
        }
      }
    }
  }, [gameState?.phase, isCoinFlipping, gameState?.mode]);

  // Tutorial Step Advancement Logic
  const advanceTutorialStep = (actionType: 'CLICK_CARD' | 'CLICK_UI_BUTTON' | 'PLAY_CARD' | 'PHASE_CHANGE' | 'DECLARE_BLOCK' | 'NONE', targetId?: string) => {
      setGameState(prev => {
          if (!prev || !prev.tutorialState || !prev.tutorialState.active) return prev;

          const step = prev.tutorialState.steps[prev.tutorialState.currentStepIndex];
          if (!step) return prev;

          // Check Requirements (Check specific requirement if strict)
          if (step.requiredAction !== 'NONE') {
               if (step.requiredAction !== actionType) return prev;
               if (step.targetId && step.targetId !== targetId) return prev;
          }

          // Advance
          const nextIndex = prev.tutorialState.currentStepIndex + 1;
          if (nextIndex < prev.tutorialState.steps.length) {
              return {
                  ...prev,
                  tutorialState: {
                      ...prev.tutorialState,
                      currentStepIndex: nextIndex
                  }
              };
          } else {
              // End Tutorial and Save Progress
              if (prev.tutorialState.lessonId) {
                  localStorage.setItem(`battle_lesson_complete_${prev.tutorialState.lessonId}`, 'true');
              }
              return {
                  ...prev,
                  tutorialState: { ...prev.tutorialState, active: false, completed: true },
                  logs: addLog(prev, "Lesson Complete!")
              };
          }
      });
  };

  // Generic handler for "NONE" action tutorial steps (click anywhere to advance)
  const handleGlobalClick = () => {
      if (gameState?.tutorialState?.active) {
          const step = gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex];
          if (step && step.requiredAction === 'NONE') {
              advanceTutorialStep('NONE');
          }
      }
  };

  // Specifically for the "Next" button in tutorial overlay
  const handleTutorialNext = () => {
      const state = gameStateRef.current;
      // Special logic for Lesson 2 flow control (force block confirm after watching)
      if (state?.mode === 'TUTORIAL' && state.tutorialState?.lessonId === 'lesson-2') {
          const stepId = state.tutorialState.steps[state.tutorialState.currentStepIndex]?.id;
          if (stepId === 'l2-block-watch') {
              // User watched the block, now clicking next triggers the resolution
              confirmBlocks(); // Force proceed to damage
          }
          else if (stepId === 'l2-result-expl') {
              // After "You protected your life total", P2 ends turn
              performEndTurn(); 
          }
      }

      advanceTutorialStep('CLICK_UI_BUTTON', 'btn-tutorial-next');
  };

  const isInteractionAllowed = (interactionId: string): boolean => {
      const state = gameStateRef.current;
      if (!state || state.mode !== 'TUTORIAL' || !state.tutorialState || !state.tutorialState.active) {
          return true; // Not in tutorial mode, everything allowed
      }

      const step = state.tutorialState.steps[state.tutorialState.currentStepIndex];
      // If action is NONE, block everything except overlay (which is handled separately)
      if (step.requiredAction === 'NONE') return false; 

      return step ? step.allowedInteractionIds?.includes(interactionId) ?? false : false;
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.mode === 'SANDBOX') {
          if (state.isSandboxRun) return state.turnPlayer;
          return state.turnPlayer; 
      }
      if (state.phase === Phase.INIT_SELECT && state.players[1].isCpu && !state.players[0].isCpu) {
          // Classic P1 setup vs CPU case
          return 0;
      }
      if (state.phase === Phase.BLOCK_DECLARE) return state.turnPlayer === 0 ? 1 : 0;
      return state.turnPlayer;
  };

  useEffect(() => {
      // Pause CPU if menu is open or turn animation is playing
      if (showMenu || showTurnAnim || !gameState || gameState.phase === Phase.GAME_OVER || isCoinFlipping) return;
      if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) return; 
      if (gameState.mode === 'TUTORIAL') return; // Tutorial handles its own scripted moves

      const activePlayerId = getActiveDecisionPlayerId(gameState);
      const activePlayer = gameState.players[activePlayerId];

      // If active player is CPU, execute turn
      if (activePlayer.isCpu) {
          // Variable thinking time: 1.5s to 3s
          const thinkTime = 1500 + Math.random() * 1500;
          const timer = setTimeout(async () => { await executeCpuTurn(); }, thinkTime); 
          return () => clearTimeout(timer);
      }
  }, [gameState?.phase, gameState?.turnPlayer, gameState?.turnCount, gameState?.players, isCoinFlipping, gameState?.mode, gameState?.isSandboxRun, showMenu, showTurnAnim]);

  const executeCpuTurn = async () => {
      const state = gameStateRef.current;
      if (!state) return;
      const activePlayerId = getActiveDecisionPlayerId(state);
      const cpu = state.players[activePlayerId];

      switch(state.phase) {
          case Phase.INIT_SELECT:
              // Setup Phase CPU Logic
              if (state.initSelectedIds.length === 0) {
                  const cpuIds = getCpuInitSelection(cpu.hand);
                  // Simulate Selection
                  setGameState(prev => {
                      if(!prev) return null;
                      return { ...prev, initSelectedIds: cpuIds };
                  });
                  await new Promise(r => setTimeout(r, 800));
                  handleConfirmInitSelection();
              }
              break;
          case Phase.RESOURCE_START:
              const resDecision = getCpuResourceDecision(cpu, state.turnCount);
              if (resDecision.action === 'SKIP') {
                  advancePhase(Phase.MAIN);
              } else if (resDecision.action === 'ADD' && resDecision.cardIdToAdd) {
                  const card = cpu.hand.find(c => c.id === resDecision.cardIdToAdd);
                  if (card) {
                      advancePhase(Phase.RESOURCE_ADD_SELECT);
                      await new Promise(r => setTimeout(r, 500));
                      await handleCardClick(card, 'HAND', activePlayerId, undefined, true);
                  }
              } else if (resDecision.action === 'SWAP') { advancePhase(Phase.MAIN); }
              break;
          case Phase.MAIN:
              const action = getBestMainPhaseAction(state);
              if (action.type === 'END_TURN') {
                  const possibleAttackers = getCpuAttackers(state);
                  if (!cpu.hasAttackedThisTurn && possibleAttackers.length > 0) { advancePhase(Phase.ATTACK_DECLARE); } 
                  else { performEndTurn(); }
              } 
              else if (action.type === 'PLAY_UNIT' && action.cardId) {
                  const card = cpu.hand.find(c => c.id === action.cardId);
                  if(card) playCardImmediate(card); 
              }
              else if (action.type === 'PLAY_TACTIC' && action.cardId) {
                  const card = cpu.hand.find(c => c.id === action.cardId);
                  if (card) {
                      // Fix: Correctly identify the target owner. The utils function returns an instanceId.
                      let targetOwnerId = 0; // Default
                      if (action.targetId) {
                          const opponentId = activePlayerId === 0 ? 1 : 0;
                          // Check opponent first (most likely)
                          if (state.players[opponentId].field.some(f => f.instanceId === action.targetId)) {
                              targetOwnerId = opponentId;
                          } else if (state.players[activePlayerId].field.some(f => f.instanceId === action.targetId)) {
                              targetOwnerId = activePlayerId;
                          }
                      }
                      playCardImmediate(card, action.targetId, targetOwnerId);
                  }
              }
              break;
          case Phase.ATTACK_DECLARE:
              const attackerIds = getCpuAttackers(state);
              if (attackerIds.length > 0) {
                  setGameState(prev => ({ ...prev!, pendingAttackers: attackerIds }));
                  await new Promise(r => setTimeout(r, 500));
                  confirmAttack();
              } else { advancePhase(Phase.MAIN); }
              break;
          case Phase.BLOCK_DECLARE:
              // For blocks, activePlayerId is the Defender
              const blocks = getCpuBlocks(state, activePlayerId);
              setGameState(prev => ({ ...prev!, pendingBlocks: blocks }));
              await new Promise(r => setTimeout(r, 500));
              confirmBlocks();
              break;
      }
  };

  const formatCardLog = (card: Card) => `[${card.rank}${card.suit}]`;

  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;
      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);
      return canPlayCard || canAttack;
  };

  // ... (Utils like triggerFlyer, triggerExplosion, drawCards, etc. preserved) ...
  const triggerFlyer = async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
      return new Promise(resolve => {
          const id = generateId();
          const newFly: FlyingCard = {
              id, card, startX: startRect.left, startY: startRect.top, targetX: targetRect.left + targetRect.width / 2 - 20, targetY: targetRect.top + targetRect.height / 2 - 30
          };
          setFlyingCards(prev => [...prev, newFly]);
          setTimeout(() => { setFlyingCards(prev => prev.filter(f => f.id !== id)); resolve(); }, 600);
      });
  };

  const triggerExplosion = (instanceId: string) => {
      const el = document.getElementById(instanceId);
      if (el) {
          const rect = el.getBoundingClientRect();
          setExplosions(prev => [...prev, { id: generateId(), x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }]);
      }
  };

  const drawCards = async (playerId: number, count: number) => {
      const startState = gameStateRef.current;
      if (!startState) return;
      const pIndex = startState.players.findIndex(p => p.id === playerId);
      // Logic for Spectate: We always render the board from P0 view, but actions happen for both
      const isHotseat = !startState.players[1].isCpu || startState.players[0].isCpu; // Treat Spectate like hotseat for rendering purposes? 
      // Actually, if Spectate, we might just keep P0 at bottom.
      const isSpectate = startState.players[0].isCpu && startState.players[1].isCpu;

      const viewId = (isHotseat && !isSpectate) ? startState.turnPlayer : 0;
      const isBottom = playerId === viewId;

      const deck = startState.mode === 'STREET' || startState.mode === 'TUTORIAL' ? startState.deck : startState.players[pIndex].library;
      const availableCount = deck.length;
      const cardsToDraw = deck.slice(0, Math.min(count, availableCount));
      const failuresNeeded = count - cardsToDraw.length;

      for (const card of cardsToDraw) {
           let startRect = isBottom ? bottomDeckRef.current?.getBoundingClientRect() : topDeckRef.current?.getBoundingClientRect();
           let targetRect = isBottom ? handRef.current?.getBoundingClientRect() : cpuHandRef.current?.getBoundingClientRect();

           // Fallback for spectate if animating the 'top' player (P1)
           if (isSpectate && playerId === 1) {
               startRect = topDeckRef.current?.getBoundingClientRect();
               targetRect = cpuHandRef.current?.getBoundingClientRect();
           }

           if (startRect && targetRect) { triggerFlyer(card, startRect, targetRect); }

           setGameState(prev => {
               if (!prev) return null;
               const nextPlayers = [...prev.players];
               const nextP = { ...nextPlayers[pIndex] };
               let nextDeck = prev.deck;
               if (prev.mode === 'STREET' || prev.mode === 'TUTORIAL') { nextDeck = prev.deck.filter(c => c.id !== card.id); } 
               else { nextP.library = nextP.library.filter(c => c.id !== card.id); }
               nextP.hand = [...nextP.hand, card];
               if (autoSort) nextP.hand = sortHand(nextP.hand);
               nextPlayers[pIndex] = nextP;
               return { ...prev, deck: prev.mode === 'STREET' || prev.mode === 'TUTORIAL' ? nextDeck : prev.deck, players: nextPlayers };
           });
           await new Promise(r => setTimeout(r, 60));
      }
      if (cardsToDraw.length > 0) { setGameState(prev => prev ? { ...prev, logs: addLog(prev, `${startState.players[pIndex].name} drew ${cardsToDraw.length} cards.`) } : null); }
      if (failuresNeeded > 0) {
          setGameState(prev => {
               if (!prev) return null;
               const nextPlayers = prev.players.map(pl => pl.id === playerId ? { ...pl, consecutiveDrawFailures: pl.consecutiveDrawFailures + failuresNeeded } : pl);
               return { ...prev, players: nextPlayers, logs: addLog(prev, "Deck Empty!") };
          });
          setTimeout(() => { if (gameStateRef.current) checkGameOver(gameStateRef.current); }, 100);
      }
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      setShowResignModal(false); setShowMenu(false);
  };

  const toggleAutoSort = () => {
      setAutoSort(prev => !prev);
      setGameState(prev => {
          if(!prev) return null;
          if (!autoSort) { 
             const activePid = getActiveDecisionPlayerId(prev);
             const nextPlayers = [...prev.players];
             nextPlayers[activePid].hand = sortHand(nextPlayers[activePid].hand);
             return { ...prev, players: nextPlayers };
          }
          return prev;
      });
  };

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };
      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
             if (p.id === newState.turnPlayer) {
                 p.field.forEach(c => { c.isTapped = false; c.isSummoningSick = false; });
                 p.resources.forEach(r => r.isTapped = false);
             }
          });
          newState.pendingAttackers = []; newState.pendingBlocks = {}; newState.selectedCardId = null; newState.recentDamage = {}; newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;
          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;
        case Phase.DRAW:
            // Tutorial skip draw
            if (newState.mode === 'TUTORIAL') {
                setTimeout(() => advancePhase(Phase.MAIN), 400);
                return { ...newState, phase: Phase.RESOURCE_START };
            }

            setTimeout(() => {
                drawCards(player.id, 1).then(() => {
                     setGameState(current => {
                         if(!current) return null;
                         const p = current.players[current.turnPlayer];
                         const isTurn1FirstPlayer = current.turnCount === 1 && current.turnPlayer === current.startingPlayerId;
                         const hasMaxResources = p.resources.length >= MAX_RESOURCES;
                         if (isTurn1FirstPlayer || hasMaxResources) {
                            setTimeout(() => advancePhase(Phase.MAIN), 400);
                            return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, isTurn1FirstPlayer ? "Turn 1: Resource Step skipped." : "Max Resources reached.") };
                         } else { return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") }; }
                     });
                });
            }, 0);
            break;
        case Phase.RESOURCE_START: break;
        case Phase.MAIN: newState.logs = addLog(newState, "Main Phase."); break;
        case Phase.ATTACK_DECLARE: newState.logs = addLog(newState, "Declare Attackers."); break;
        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;
      }
      return newState;
    });

    // Tutorial Check
    if (gameState?.tutorialState?.active) {
        setTimeout(() => advanceTutorialStep('PHASE_CHANGE'), 100);
    }
  };

  const handleAttackPhaseClick = () => {
      if (gameState?.tutorialState?.active) {
          if (!isInteractionAllowed('btn-attack-phase')) return;
          advanceTutorialStep('CLICK_UI_BUTTON', 'btn-attack-phase');
      }
      advancePhase(Phase.ATTACK_DECLARE);
  };

  const confirmAttack = () => {
      if (gameState?.tutorialState?.active) {
          if (!isInteractionAllowed('btn-confirm-attackers')) return;
          advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-attackers');
      }

      setGameState(prev => {
          if(!prev) return null;

          // Tutorial Scripting: Lesson 2 Attack
          if (prev.mode === 'TUTORIAL' && prev.tutorialState?.lessonId === 'lesson-2' && prev.turnPlayer === 0 && prev.phase === Phase.ATTACK_DECLARE) {
               // If this is the second turn attack (attacking with 6S now)
               if (prev.turnCount > 1) {
                   const p = prev.players[0];
                   const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
                   const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
                   p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
                   p.hasAttackedThisTurn = true;
                   // P2 has no valid defenders (5H is tapped, 2S is dead)
                   return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
               }

               // Scripted Block for First Turn
               // P2 blocks P1's 2C with 2S
               const blocks: Record<string, string> = {};
               blocks['tut-2-♠'] = 'tut-2-♣';

               const p = prev.players[0];
               const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
               const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
               p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
               p.hasAttackedThisTurn = true;

               return { ...prev, pendingBlocks: blocks, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
          }

          if (prev.pendingAttackers.length === 0) return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          const p = prev.players[prev.turnPlayer];
          const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
          const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
          p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
          p.hasAttackedThisTurn = true;
          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const attackingColors = new Set(attackers.map(getEffectiveColor));
          const untappedDefenders = defender.field.filter(f => !f.isTapped);
          const canDefend = untappedDefenders.some(def => attackingColors.has(getEffectiveColor(def)));
          if (!canDefend) return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
      });
  };

  const confirmBlocks = () => { 
      if (gameState?.tutorialState?.active) {
          if (!isInteractionAllowed('btn-confirm-blocks') && !isInteractionAllowed('btn-tutorial-next')) return; // Allow from both button and overlay next
          advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-blocks');
      }
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null); 
  };
  const requestEndTurn = () => { 
      if (!isInteractionAllowed('btn-end-turn')) return;
      setShowEndTurnModal(true); 
  };
  const performEndTurn = () => {
    setGameState(prev => {
        if(!prev) return null;

        // Tutorial Scripting: Lesson 2 End Turn (Trigger P2 Attack)
        if (prev.mode === 'TUTORIAL' && prev.tutorialState?.lessonId === 'lesson-2') {
             if (prev.turnPlayer === 0) {
                 // Force P2 Attack with 5H
                const nextPlayers = [...prev.players];
                const p2 = { ...nextPlayers[1] };
                p2.field = p2.field.map(f => {
                    if (f.instanceId === 'tut-5-♥') return { ...f, isTapped: true };
                    return f;
                });
                nextPlayers[1] = p2;

                const nextState = { ...prev, players: nextPlayers, turnPlayer: 1, phase: Phase.BLOCK_DECLARE }; 
                nextState.pendingAttackers = ['tut-5-♥'];
                nextState.logs = addLog(nextState, "CPU 2 attacks with [5♥].");
                return nextState;
             }
             else if (prev.turnPlayer === 1) {
                 // FIX for Stuck State: When P2 (CPU) ends turn, force reset correctly to P1 Main Phase
                 const nextPlayers = prev.players.map(p => ({
                     ...p,
                     hasAttackedThisTurn: false, // Reset attack flag for both
                     // Untap if it's Player 1 (who is about to start turn)
                     // FIX: Also clear summoning sickness so the 6 can attack
                     field: p.id === 0 ? p.field.map(f => ({...f, isTapped: false, isSummoningSick: false})) : p.field,
                     resources: p.id === 0 ? p.resources.map(r => ({...r, isTapped: false})) : p.resources
                 }));

                 const nextState = { 
                     ...prev, 
                     players: nextPlayers,
                     turnPlayer: 0, 
                     turnCount: prev.turnCount + 1, 
                     phase: Phase.MAIN,
                     logs: addLog(prev, "Your Turn.")
                 };

                 setTimeout(() => advanceTutorialStep('PHASE_CHANGE'), 100);

                 return nextState;
             }
        }

        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;
        const nextState = { ...prev, turnPlayer: nextPlayerIdx, turnCount: nextTurnCount, phase: Phase.UPKEEP };
        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return nextState; 
    });
    // Trigger interstitial animation
    setShowTurnAnim(true);
  };
  const confirmEndTurn = () => { 
      if (gameState?.tutorialState?.active) {
          if(!isInteractionAllowed('btn-end-turn-modal-confirm')) return; // Allow modal confirm specifically
          advanceTutorialStep('CLICK_UI_BUTTON', 'btn-end-turn');
      }
      setShowEndTurnModal(false); 
      performEndTurn(); 
  };

  useEffect(() => { if (gameState?.phase === Phase.DAMAGE) executeCombatSequence(); }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();
      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));
      const directAttackers = attackers.filter(atk => !Object.values(state.pendingBlocks).includes(atk.instanceId));

      const delayPre = 100;
      const delayPost = 300; // Small delay between attacks

      // 1. Process Blocked Combats
      for (const atk of attackers) {
          const blockerId = Object.keys(state.pendingBlocks).find(k => state.pendingBlocks[k] === atk.instanceId);
          if (blockerId) {
                setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
                await new Promise(r => setTimeout(r, 400));
                setGameState(prev => {
                    if (!prev) return null;
                    const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                    if (!blk) return prev;
                    const nextRecentDamage = { ...prev.recentDamage };
                    nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                    nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                    const logMsg = `⚔️ Battle: ${formatCardLog(atk.card)} (${atk.card.numericValue}) vs ${formatCardLog(blk.card)} (${blk.card.numericValue})`;
                    return { ...prev, recentDamage: nextRecentDamage, logs: addLog(prev, logMsg) };
                });
                await new Promise(r => setTimeout(r, 600)); 
                setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
                await new Promise(r => setTimeout(r, 100));
          }
      }

      // 2. Process Direct Attacks
      for (const atk of directAttackers) {
           setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
           await new Promise(r => setTimeout(r, delayPre));

           const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;

           // Create callback to apply damage AFTER animation
           const applyDamage = () => {
               setGameState(prev => {
                   if (!prev) return null;
                   const nextPlayers = [...prev.players];
                   const defIdx = nextPlayers.findIndex(p => p.id === defenderPlayer.id);
                   if (defIdx > -1) { 
                       nextPlayers[defIdx] = { ...nextPlayers[defIdx], life: Math.max(0, nextPlayers[defIdx].life - dmg) }; 
                   }

                   let nextState = { ...prev, players: nextPlayers };
                   if (nextPlayers[defIdx].life <= 0 && nextState.winner === null) {
                       nextState.winner = attackerPlayer.id;
                       nextState.phase = Phase.GAME_OVER;
                   }
                   return nextState;
               });
           };

           // Push new animation (component handles lifecycle and callback)
           setDamageAnims(prev => [...prev, { id: generateId(), val: dmg, playerId: defenderPlayer.id, onApply: applyDamage }]);

           setGameState(prev => {
               if(!prev) return null;
               // Log only, update life later via callback
               return { ...prev, logs: addLog(prev, `🔥 Direct Hit! ${formatCardLog(atk.card)} deals ${dmg} damage.`) };
           });

           // Slight delay so they don't stack instantly
           await new Promise(r => setTimeout(r, delayPost));
           setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
      }

      // 3. Cleanup & Death
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];
          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);
              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue; const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A'; const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false; let blkDies = false;
                      if (atkIsAce) blkDies = true; if (blkIsAce) atkDies = true;
                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true; else if (blkVal > atkVal) atkDies = true; else { atkDies = true; blkDies = true; }
                      } else { if(atkIsAce && !blkIsAce) atkDies = true; if(blkIsAce && !atkIsAce) blkDies = true; }

                      if (atkDies) { triggerExplosion(atk.instanceId); atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId); atkP.discard.push(atk.card, ...atk.attachedCards); }
                      if (blkDies) { triggerExplosion(blk.instanceId); defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId); defP.discard.push(blk.card, ...blk.attachedCards); }
                  }
              } 
          });
          nextState.recentDamage = {}; nextState.pendingAttackers = []; nextState.pendingBlocks = {}; nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;
          return nextState;
      });
  };

  // ... (Drag handlers preserved) ...
  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      if (gameState.mode === 'TUTORIAL') {
          const id = instanceId || card.id;
          if (!isInteractionAllowed(id)) return;
      }

      if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) {
           setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
           return;
      }
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      // Prevent drag interaction if player is CPU (Spectate/Pause safety)
      if (gameState.players[activePid].isCpu) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }
      setDragState({ cardId: card.id, sourceType: type, ownerId, startX: e.clientX, startY: e.clientY, currentX: e.clientX, currentY: e.clientY, cardObj: card, instanceId });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');
      if (!targetElement) return;
      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) { handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined); }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) { handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId); }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const player = gameState.players[gameState.turnPlayer];
      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) { setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") })); return; }
      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => { if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id; });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else { playCardImmediate(card); }
  };

  const playCardImmediate = async (card: Card, targetId?: string, targetOwnerId?: number) => {
       let cardIdx = -1; let playedCard: Card | null = null;
       const isFaceCard = ['K', 'Q', 'J'].includes(card.rank);

       // VALIDATION BEFORE ANIMATION
       const currentState = gameStateRef.current;
       if (!currentState) return;

       if (card.rank === 'K') {
           if (!targetId || targetOwnerId === undefined) return;
           const targetP = currentState.players.find(p => p.id === targetOwnerId);
           const targetF = targetP?.field.find(f => f.instanceId === targetId);
           if (!targetF) return; // Target gone?
           if (getEffectiveColor(targetF) !== card.baseColor) { 
               // Invalid Target
               setGameState(prev => prev ? ({ ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") }) : null);
               return; 
           }
       } else if (card.rank === 'Q') {
           if (!targetId || targetOwnerId === undefined) return;
           const targetP = currentState.players.find(p => p.id === targetOwnerId);
           const targetF = targetP?.field.find(f => f.instanceId === targetId);
           if (!targetF) return; // Invalid target
       }

       if (isFaceCard) {
           let targetRect: DOMRect | undefined;
           if (targetId) { const targetEl = document.getElementById(targetId); if (targetEl) targetRect = targetEl.getBoundingClientRect(); }
           setSpecialAnim({ type: card.rank as 'K'|'Q'|'J', card, targetRect });
           await new Promise(r => setTimeout(r, card.rank === 'K' ? 1200 : card.rank === 'Q' ? 1000 : 800));
           setSpecialAnim(null);
       } else {
           // Normal Soldier Play Animation (Skip if dragging)
           if (!dragState) {
               const cardEl = document.getElementById(card.id);
               const fieldEl = document.getElementById('field-area');
               if (cardEl && fieldEl) {
                   await triggerFlyer(card, cardEl.getBoundingClientRect(), fieldEl.getBoundingClientRect());
               }
           }
       }

       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;
           const newHand = [...p.hand];
           [playedCard] = newHand.splice(cardIdx, 1);
           let toTap = card.cost;
           const newResources = p.resources.map(r => {
               if (!r.isTapped && toTap > 0) { toTap--; return { ...r, isTapped: true }; }
               return r;
           });
           const nextState = { ...prev, players: [...prev.players] };
           const nextPlayer = { ...p, hand: newHand, resources: newResources };
           nextState.players[prev.turnPlayer] = nextPlayer;
           if (card.rank === 'J') { nextPlayer.discard.push(playedCard!); return { ...nextState, logs: addLog(nextState, `Played Jack ${formatCardLog(card)}.`) }; }
           else if (card.rank === 'K') {
               const targetP = nextState.players[targetOwnerId!];
               const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
               if (targetFIdx === -1) return prev; 
               const targetF = targetP.field[targetFIdx];
               // Double check inside state update just in case state changed during animation
               if (getEffectiveColor(targetF) !== card.baseColor) { return { ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") }; }
               triggerExplosion(targetId!); nextPlayer.discard.push(playedCard!); targetP.field.splice(targetFIdx, 1); targetP.discard.push(targetF.card, ...targetF.attachedCards);
               return { ...nextState, logs: addLog(nextState, `King ${formatCardLog(card)} executed ${formatCardLog(targetF.card)}.`) };
           }
           else if (card.rank === 'Q') {
               const targetP = nextState.players[targetOwnerId!];
               const targetF = targetP.field.find(f => f.instanceId === targetId);
               if(targetF) {
                   const existingQueens = targetF.attachedCards.filter(c => c.rank === Rank.Queen);
                   if (existingQueens.length > 0) { targetP.discard.push(...existingQueens); targetF.attachedCards = targetF.attachedCards.filter(c => c.rank !== Rank.Queen); }
                   targetF.attachedCards.push(playedCard!);
               }
               return { ...nextState, logs: addLog(nextState, `Queen ${formatCardLog(card)} shifted ${targetF ? formatCardLog(targetF.card) : 'target'}.`) };
           }
           else {
               // FIX: For Tutorial, ensure Instance ID matches Card ID for highlighting
               const newSoldier = createFieldCard(playedCard!, p.id); 
               if (prev.mode === 'TUTORIAL') {
                   newSoldier.instanceId = card.id;
               }
               nextPlayer.field.push(newSoldier);
               return { ...nextState, logs: addLog(nextState, `Conscripted ${formatCardLog(card)}.`) };
           }
       });
       if (card.rank === 'J' && gameState) { await drawCards(gameState.turnPlayer, 2); }

       if (gameState?.tutorialState?.active) {
           // Small delay to let React render the new field card so highlight can find it
           setTimeout(() => {
               advanceTutorialStep('PLAY_CARD', card.id);
           }, 100);
       }
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;
          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = prev.players[prev.turnPlayer].field.find(f => f.instanceId === attackerInstanceId);
          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });

      // Tutorial Step Advance for Block Declare
      if (gameState?.tutorialState?.active) {
          advanceTutorialStep('DECLARE_BLOCK', blockerInstanceId);
      }
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string, fromCpu: boolean = false) => {
      const currentState = gameStateRef.current;
      if (!currentState) return;

      // Tutorial Blocking
      const elementId = instanceId || card.id;
      if (currentState.mode === 'TUTORIAL') {
          if (!isInteractionAllowed(elementId)) {
              console.log("Tutorial Blocked Interaction:", elementId);
              return;
          }
      }

      if (currentState.mode === 'SANDBOX' && !currentState.isSandboxRun) { setCardActionTarget({ card, loc: location, ownerId, instanceId }); return; }

      const activePlayerId = getActiveDecisionPlayerId(currentState);
      if (!fromCpu && currentState.players[activePlayerId].isCpu && ownerId === activePlayerId) { if (currentState.phase !== Phase.INIT_SELECT) return; }

      if (currentState.phase === Phase.INIT_SELECT && location === 'HAND') {
          if (ownerId === activePlayerId) {
              setGameState(prev => {
                  if(!prev) return null;
                  const isSelected = prev.initSelectedIds.includes(card.id);
                  let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
                  if (newIds.length > 3) newIds.pop();
                  return { ...prev, initSelectedIds: newIds };
              });

              if (currentState.mode === 'TUTORIAL') {
                  advanceTutorialStep('CLICK_CARD', card.id);
              }
          }
      }
      else if (currentState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
          let cardEl = document.getElementById(card.id); 
          if (cardEl && targetResourceContainer) { await triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect()); }
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));
             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, `${p.name} converted ${formatCardLog(resCard)} into a resource.`) };
          });
          await drawCards(activePlayerId, 1);
      }
      else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (currentState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          if (currentState.selectedCardId) {
              const handCardEl = document.getElementById(currentState.selectedCardId);
              const resCardEl = instanceId ? document.getElementById(instanceId) : null; 
              const handContainer = handRef.current;
              const handCard = currentState.players[activePlayerId].hand.find(c => c.id === currentState.selectedCardId);
              if (handCard && handCardEl && resCardEl && handContainer) {
                  const p1 = triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                  const p2 = triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                  await Promise.all([p1, p2]);
              }
          }
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx]; const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card; p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
                  return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, `${p.name} swapped resource ${formatCardLog(resFieldCard.card)} for ${formatCardLog(handCard)}.`) };
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN };
          });
      }
      else if (currentState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });

          if (currentState.mode === 'TUTORIAL') {
              advanceTutorialStep('CLICK_CARD', card.id);
          }
      }
      else if (currentState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && currentState.pendingBlocks[instanceId]) { removeBlock(instanceId); }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const cancelResourceAction = () => {
       setGameState(prev => {
           if(!prev) return null;
           return { ...prev, phase: Phase.RESOURCE_START, selectedCardId: null };
       });
  };

  const handleConfirmInitSelection = async () => {
       const activeId = getActiveDecisionPlayerId(gameState!);
       if (gameState?.mode === 'TUTORIAL') {
           if (!isInteractionAllowed('btn-confirm-init')) return;
           advanceTutorialStep('CLICK_UI_BUTTON', 'btn-confirm-init');
       }

       // ANIMATION START: Initial Resource Send
       const p = gameState!.players[activeId];
       const selectedCards = p.hand.filter(c => gameState!.initSelectedIds.includes(c.id));
       const resContainer = document.getElementById(`resource-container-${activeId}`);

       if (resContainer) {
           const resRect = resContainer.getBoundingClientRect();
           const animations = selectedCards.map(c => {
               const el = document.getElementById(c.id);
               if (el) {
                   return triggerFlyer(c, el.getBoundingClientRect(), resRect);
               }
               return Promise.resolve();
           });
           await Promise.all(animations); // Wait for flight before updating state
       }
       // ANIMATION END

       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[activeId];
          const selected = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remaining = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remaining;
          selected.forEach(c => p.resources.push(createFieldCard(c, p.id)));
          const otherId = activeId === 0 ? 1 : 0;
          const other = prev.players[otherId];
          let nextState = { ...prev, initSelectedIds: [] };
          let gameStarting = false;

          if (other.isCpu) {
              const cpuIds = getCpuInitSelection(other.hand);
              const cpuSelected = other.hand.filter(c => cpuIds.includes(c.id));
              const cpuRemaining = other.hand.filter(c => !cpuIds.includes(c.id));
              other.hand = cpuRemaining;
              cpuSelected.forEach(c => { other.resources.push(createFieldCard(c, other.id)); });
              nextState.logs = addLog(nextState, "Battle Commencing!");
              nextState.phase = Phase.UPKEEP; nextState.turnPlayer = prev.startingPlayerId; 
              gameStarting = true;
              setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 500);
          } else {
              // Check if opponent is already done (meaning resources > 0, actually 3)
              // Wait, checking `other.resources.length === 3` checks if the inactive player is set up.
              // If P1 confirms first, P2 has 0 resources. other(P2).resources = 0.
              // If P2 confirms second, P1 has 3 resources. other(P1).resources = 3.
              if (other.resources.length === 3) {
                  nextState.logs = addLog(nextState, "Battle Commencing!");
                  nextState.phase = Phase.UPKEEP; nextState.turnPlayer = prev.startingPlayerId;
                  gameStarting = true;
                  setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 500);
              } else { 
                  nextState.turnPlayer = otherId; 
                  nextState.logs = addLog(nextState, `${other.name}'s turn to setup.`); 
              }
          }

          if (gameStarting) {
              setTimeout(() => setShowTurnAnim(true), 100);
          }

          return nextState;
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.RESOURCE_ADD_SELECT: return "Select Card";
        case Phase.RESOURCE_SWAP_SELECT_HAND: return "Select to Swap";
        case Phase.RESOURCE_SWAP_SELECT_PILE: return "Select Pile";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        case Phase.UPKEEP: return "Upkeep";
        case Phase.DRAW: return "Draw Step";
        case Phase.END: return "End Phase";
        case Phase.GAME_OVER: return "Game Over";
        default: return gameState?.phase || "";
    }
  };

  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'SANDBOX') { startGame('SANDBOX', { p1: false, p2: false }); } 
      else if (mode === 'TUTORIAL') { 
          // Switch to Tutorial Submenu instead of starting immediately
          setMenuStep('TUTORIAL_MENU');
      }
      else { setSelectedMode(mode); setMenuStep('PLAYERS'); }
  };

  const startLesson = (lessonId: string) => {
      startGame('TUTORIAL', { p1: false, p2: true }, lessonId);
  };

  const handleStartGameClick = (isCpu: boolean) => {
      if (selectedMode) { startGame(selectedMode, { p1: false, p2: isCpu }); }
  };

  const handleSpectateClick = () => {
      if (selectedMode) { startGame(selectedMode, { p1: true, p2: true }); }
  };

  const executeCardAction = (action: 'TAP' | 'DELETE') => {
      if (!cardActionTarget) return;
      setGameState(prev => {
          if(!prev) return null;
          const nextState = { ...prev, players: [...prev.players] };
          const p = nextState.players.find(pl => pl.id === cardActionTarget.ownerId)!;
          if (cardActionTarget.loc === 'HAND') {
              if (action === 'DELETE') { p.hand = p.hand.filter(c => c.id !== cardActionTarget.card.id); }
          } else if (cardActionTarget.loc === 'FIELD') {
              if (action === 'DELETE') { p.field = p.field.filter(c => c.instanceId !== cardActionTarget.instanceId); } 
              else if (action === 'TAP') { const fc = p.field.find(c => c.instanceId === cardActionTarget.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          } else if (cardActionTarget.loc === 'RESOURCE') {
               if (action === 'DELETE') { p.resources = p.resources.filter(c => c.instanceId !== cardActionTarget.instanceId); } 
               else if (action === 'TAP') { const fc = p.resources.find(c => c.instanceId === cardActionTarget.instanceId); if(fc) fc.isTapped = !fc.isTapped; }
          }
          return nextState;
      });
      setCardActionTarget(null);
  };

  const startPlayFromHere = (isCpu: boolean) => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'STREET', phase: Phase.MAIN, isSandboxRun: true, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu } : p) };
      });
      setShowPlaySetup(false); setSandboxToolsOpen(false);
  };

  const returnToSandbox = () => {
      setGameState(prev => {
          if(!prev) return null;
          return { ...prev, mode: 'SANDBOX', isSandboxRun: false, players: prev.players.map(p => p.id === 1 ? { ...p, isCpu: false } : p) };
      });
      setSandboxToolsOpen(true);
  };

  const handleQuitToTitle = () => {
      const isTutorial = gameState?.mode === 'TUTORIAL';
      setGameState(null);
      setShowQuitModal(false);
      setShowMenu(false);

      // Redirect to Tutorial Menu if exiting a tutorial
      if (isTutorial) {
          setMenuStep('TUTORIAL_MENU');
      } else {
          setMenuStep('MODE');
      }
  };

  // Memoize turn complete handler to prevent TurnChangeOverlay resets
  const handleTurnAnimComplete = useCallback(() => {
      setShowTurnAnim(false);
  }, []);

  if (!gameState) {
      return (
        <div className="relative flex flex-col items-center justify-center h-screen w-full bg-slate-950 overflow-hidden selection:bg-indigo-500/30">
            {/* Animated Background Elements */}
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black z-0"></div>
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] opacity-30 z-0"></div>

            {/* Floating Suits Background */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none z-0 opacity-20">
                <div className="absolute top-[10%] left-[10%] text-[12rem] text-slate-800 rotate-12 animate-pulse duration-[3000ms]">♠</div>
                <div className="absolute bottom-[10%] right-[5%] text-[14rem] text-red-900 -rotate-12 animate-pulse duration-[4000ms]">♥</div>
                <div className="absolute top-[20%] right-[15%] text-[10rem] text-slate-800 rotate-45 animate-pulse duration-[5000ms]">♣</div>
                <div className="absolute bottom-[20%] left-[8%] text-[11rem] text-red-900 -rotate-45 animate-pulse duration-[3500ms]">♦</div>
            </div>

            <MainMenu 
                menuStep={menuStep}
                setMenuStep={setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGameClick}
                handleSpectateClick={handleSpectateClick}
                startLesson={startLesson}
            />
        </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);

  // HOTSEAT / SANDBOX View Logic
  // In Sandbox, View is determined by turnPlayer state which is manually toggled via "Switch Perspective"
  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';

  // View Flipping Logic for Hotseat:
  // If Hotseat mode, view should follow the Active Decision Player.
  // Exception: In Sandbox, manual toggle sets turnPlayer, so it follows turnPlayer.
  // getActiveDecisionPlayerId handles the logic for BLOCK_DECLARE swapping active ID to defender.
  const viewPlayerId = isHotseat ? activeDecisionPlayerId : 0; 

  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];

  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) && !gameState.isSandboxRun ? '' : 'ring-2 ring-indigo-400 animate-pulse';
  const isPlayerTurn = activeDecisionPlayerId === viewPlayerId;
  const isActivePlayerCpu = gameState.players[activeDecisionPlayerId].isCpu;

  // Interactive if it is the player's turn AND the player is NOT a CPU
  const isInteractive = isPlayerTurn && !isActivePlayerCpu;

  const tutorialComplete = gameState.tutorialState?.completed;

  return (
    <div 
      className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" 
      ref={containerRef}
      onMouseMove={(e) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      }}
      onMouseUp={(e) => {
          if (dragState) {
              handleDrop(e.nativeEvent, dragState);
              setDragState(null);
          }
      }}
      onClick={() => handleGlobalClick()}
    >
      {/* Coin Flip Overlay */}
      {isCoinFlipping && (
           <CoinFlipOverlay 
                p1Name={gameState.players[0].name} 
                p2Name={gameState.players[1].name} 
                onComplete={(winner) => {
                    setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null);
                    setIsCoinFlipping(false);
                }} 
           />
      )}

      {/* Tutorial Overlay */}
      {gameState.tutorialState?.active && !tutorialComplete && gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex] && (
          <TutorialOverlay 
            step={gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex]} 
            onNext={handleTutorialNext}
          />
      )}

      {/* Tutorial Complete Screen */}
      {tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <GraduationCap className="w-24 h-24 mx-auto text-emerald-500 animate-bounce" />
                  <h1 className="text-5xl md:text-7xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-500 drop-shadow-[0_0_25px_rgba(16,185,129,0.5)]">
                      TUTORIAL COMPLETE
                  </h1>
                  <h2 className="text-2xl text-slate-300">You have mastered the basics!</h2>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-bold text-xl shadow-lg shadow-emerald-500/30 transform transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                          <RotateCcw size={20} /> Return to Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Return to Sandbox Button */}
      {gameState.isSandboxRun && (
          <div className="absolute top-16 left-4 z-50 animate-in fade-in slide-in-from-top">
              <button onClick={returnToSandbox} className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2">
                  <RotateCcw size={18}/> Return to Sandbox
              </button>
          </div>
      )}

      {/* Play Setup Modal */}
      {showPlaySetup && (
          <div className="absolute inset-0 z-[100] bg-black/80 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 w-80">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2"><Play size={20} className="text-emerald-400"/> Play Scenario</h3>
                  <div className="space-y-3">
                      <button onClick={() => startPlayFromHere(true)} className="w-full bg-slate-800 hover:bg-emerald-900/30 border border-slate-700 hover:border-emerald-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Cpu size={18}/> Vs CPU
                      </button>
                      <button onClick={() => startPlayFromHere(false)} className="w-full bg-slate-800 hover:bg-amber-900/30 border border-slate-700 hover:border-amber-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Users size={18}/> Hotseat
                      </button>
                  </div>
                  <button onClick={() => setShowPlaySetup(false)} className="mt-4 text-slate-500 text-sm hover:text-white">Cancel</button>
              </div>
          </div>
      )}

      {/* Card Action Modal for Sandbox */}
      {cardActionTarget && (
          <div className="absolute inset-0 z-[100] bg-black/50 flex items-center justify-center" onClick={() => setCardActionTarget(null)}>
              <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 shadow-2xl transform scale-100 transition-transform" onClick={e => e.stopPropagation()}>
                  <div className="flex justify-center mb-4">
                      <CardDisplay card={cardActionTarget.card} size="lg" />
                  </div>
                  <div className="flex gap-2 justify-center">
                      {cardActionTarget.loc !== 'HAND' && (
                          <button onClick={() => executeCardAction('TAP')} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                              <RotateCcw size={16}/> Tap/Untap
                          </button>
                      )}
                      <button onClick={() => executeCardAction('DELETE')} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                          <Trash2 size={16}/> Remove
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Sandbox Floating Toggle */}
      {gameState.mode === 'SANDBOX' && !gameState.isSandboxRun && !sandboxToolsOpen && (
          <button 
            onClick={() => setSandboxToolsOpen(true)} 
            className="absolute top-20 right-4 z-50 bg-slate-800 p-3 rounded-full border border-slate-600 shadow-xl hover:bg-slate-700 text-amber-400"
          >
              <Edit3 size={24} />
          </button>
      )}

      {/* Render Sandbox Tools Panel */}
      {sandboxToolsOpen && (
          <SandboxTools 
              gameState={gameState}
              setGameState={setGameState}
              sandboxSearchTerm={sandboxSearchTerm}
              setSandboxSearchTerm={setSandboxSearchTerm}
              sandboxTargetPlayer={sandboxTargetPlayer}
              setSandboxTargetPlayer={setSandboxTargetPlayer}
              selectedSandboxCard={selectedSandboxCard}
              setSelectedSandboxCard={setSelectedSandboxCard}
              setSandboxToolsOpen={setSandboxToolsOpen}
              setShowPlaySetup={setShowPlaySetup}
          />
      )}

      {/* Turn Change Overlay */}
      {showTurnAnim && (
          <TurnChangeOverlay 
              playerName={gameState.players[gameState.turnPlayer].name}
              turnCount={gameState.turnCount}
              onComplete={handleTurnAnimComplete}
          />
      )}

      {/* Game Over Modal */}
      {gameState.phase === Phase.GAME_OVER && !tutorialComplete && gameState.mode !== 'TUTORIAL' && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">
                      GAME OVER
                  </h1>
                  <h2 className="text-3xl font-bold text-white drop-shadow-md">
                      {gameState.winner !== null ? `${gameState.players[gameState.winner].name} Wins!` : "It's a Draw!"}
                  </h2>

                  {/* Turn Count Display */}
                  <div className="text-xl text-slate-400 font-title uppercase tracking-widest mt-2">
                      Total Turns: {gameState.turnCount}
                  </div>

                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">
                          Rematch / Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Confirmation Modals */}
      <EndTurnModal show={showEndTurnModal} onCancel={() => setShowEndTurnModal(false)} onConfirm={confirmEndTurn} />
      <ResignModal show={showResignModal} onCancel={() => setShowResignModal(false)} onConfirm={handleResign} />
      <QuitModal show={showQuitModal} onCancel={() => setShowQuitModal(false)} onConfirm={handleQuitToTitle} />
      <PauseMenu 
        show={showMenu} 
        onResume={() => setShowMenu(false)} 
        onResign={() => setShowResignModal(true)} 
        onQuit={() => setShowQuitModal(true)} 
        autoSort={autoSort} 
        onToggleSort={toggleAutoSort} 
      />

      {/* Discard Modal */}
      <DiscardModal 
        viewingDiscard={viewingDiscard as 'SHARED' | number | null} 
        players={gameState.players} 
        onClose={() => setViewingDiscard(null)} 
        mode={gameState.mode} 
      />

      {specialAnim && <SpecialCardAnimation type={specialAnim.type} card={specialAnim.card} targetRect={specialAnim.targetRect} onComplete={() => setSpecialAnim(null)} />}

      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {explosions.map(e => (
          <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => setExplosions(prev => prev.filter(x => x.id !== e.id))} />
      ))}

      {damageAnims.map(da => (
          <DamageOverlay 
            key={da.id}
            dmg={da.val} 
            targetRef={da.playerId === topPlayer.id ? lifeIconRef : bottomLifeRef}
            onComplete={() => setDamageAnims(prev => prev.filter(a => a.id !== da.id))}
            onImpact={da.onApply}
          />
      ))}

      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="#3b82f6"
                        strokeWidth="4"
                        strokeDasharray="0"
                        className="opacity-70"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {isMobile ? (
          <div className="flex flex-col h-full bg-slate-950 select-none">
          {/* Mobile Top Bar: CPU Info */}
          <div className="h-14 bg-slate-900 border-b border-slate-800 flex items-center justify-between px-3 shadow-md z-30 shrink-0">
               <div className="flex items-center gap-3">
                   <button onClick={() => setShowMenu(true)} className="p-1.5 bg-slate-800 rounded text-slate-400">
                       <Menu size={18} />
                   </button>
                   <div className="flex flex-col leading-tight">
                       <span className="text-xs font-bold text-indigo-300">{topPlayer.name}</span>
                       <div className="flex items-center gap-2 text-xs text-slate-500" ref={topDeckRef}>
                           <span>Deck: {gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
                       </div>
                   </div>
               </div>

               {/* Center Turn Info */}
               <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center">
                    <span className="font-title font-bold text-amber-500 text-sm">TURN {gameState.turnCount}</span>
                    <span className="text-[10px] text-slate-400 uppercase tracking-wider">{getPhaseName()}</span>
               </div>

               <div className="flex items-center gap-3" ref={lifeIconRef}>
                   <div className="flex items-center gap-1 text-red-400 font-black text-xl">
                       <Heart size={20} fill="currentColor" /> {topPlayer.life}
                   </div>
                   {gameState.mode === 'PRO' && (
                        <button onClick={() => setViewingDiscard(topPlayer.id)} className="text-slate-500">
                            <Trash2 size={16} />
                        </button>
                   )}
               </div>
          </div>

          {/* Mobile Field Area */}
          <div id="field-area" className="flex-1 relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] overflow-hidden flex flex-col">

              {/* Log Toggle Button */}
              <button 
                onClick={() => setShowMobileLog(!showMobileLog)} 
                className={`absolute top-2 left-2 z-40 p-2 rounded-full border shadow-lg transition-colors ${showMobileLog ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-slate-900/80 border-slate-700 text-slate-400'}`}
              >
                  {showMobileLog ? <X size={16} /> : <div className="text-[10px] font-bold">LOG</div>}
              </button>

              {/* Mobile Log Overlay */}
              {showMobileLog && (
                  <div className="absolute top-12 left-2 right-2 bottom-auto max-h-48 z-40 bg-black/80 backdrop-blur-md border border-slate-700 rounded-lg overflow-y-auto p-2 flex flex-col-reverse gap-1 shadow-2xl">
                      {gameState.logs.map((log) => (
                          <div key={log.id} className="text-xs text-slate-300 border-l-2 border-indigo-500 pl-2">
                              <LogRenderer text={`${log.text}`} />
                          </div>
                      ))}
                  </div>
              )}

              {/* Top Player Zone */}
              <div className="flex-1 flex flex-col items-center justify-start py-2 space-y-2 relative">
                  {/* CPU Hand */}
                  <div className="flex -space-x-6 scale-75 opacity-90 h-12" ref={cpuHandRef}>
                       {topPlayer.hand.map(c => <CardDisplay key={c.id} domId={c.id} card={c} showBack={gameState.mode !== 'SANDBOX'} size="sm" onClick={() => handleCardClick(c, 'HAND', topPlayer.id)} />)}
                  </div>

                  {/* CPU Field & Resources Row */}
                  <div className="w-full flex justify-between px-1 items-start gap-1">
                       {/* Field (Flex, takes available space) */}
                       <div className="flex-1 flex justify-center gap-1 overflow-visible px-1 min-h-[80px]">
                            {/* Black Lane */}
                            <div className="bg-slate-900/40 p-1 rounded border border-slate-700/50 flex flex-wrap gap-1 min-w-[50px] items-start content-start justify-center">
                                {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                                    <div key={fc.instanceId} className="scale-75 origin-top -mx-2">
                                        <CardDisplay 
                                            domId={fc.instanceId}
                                            data-instance-id={fc.instanceId}
                                            card={fc.card} 
                                            isTapped={fc.isTapped}
                                            isSummoningSick={fc.isSummoningSick}
                                            size="sm"
                                            isLunging={gameState.activeCombatCardId === fc.instanceId}
                                            damageTaken={gameState.recentDamage[fc.instanceId]}
                                            attachedCards={fc.attachedCards}
                                            orientation="top"
                                            onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                        />
                                    </div>
                                ))}
                            </div>
                            {/* Red Lane */}
                            <div className="bg-red-900/20 p-1 rounded border border-red-900/30 flex flex-wrap gap-1 min-w-[50px] items-start content-start justify-center">
                                {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                                    <div key={fc.instanceId} className="scale-75 origin-top -mx-2">
                                        <CardDisplay 
                                            domId={fc.instanceId}
                                            data-instance-id={fc.instanceId}
